window.WPS = window.WPS || {};
WPS.LESSONS = WPS.LESSONS || {};
(function (L) {
  // ===== 図 =====
  var PASTPERF = '<svg viewBox="0 0 220 110" class="lz-fig" role="img" aria-label="過去完了の時間の線。電車が出たのが先、私が着いたのが後、そのあとに今がある"><line x1="10" y1="60" x2="210" y2="60" class="ax"/><path d="M203 55 L210 60 L203 65" class="ax"/><circle cx="55" cy="60" r="4" class="pt"/><circle cx="125" cy="60" r="4" class="pt"/><line x1="185" y1="52" x2="185" y2="68" class="ax"/><text x="28" y="42">電車が出た</text><text x="98" y="42">私が着いた</text><text x="180" y="42">今</text><text x="34" y="82">had left</text><text x="105" y="82">arrived</text><text x="38" y="102">大過去</text><text x="114" y="102">過去</text><text x="174" y="102">現在</text></svg>';
  var FUTPERF = '<svg viewBox="0 0 240 120" class="lz-fig" role="img" aria-label="未来完了の時間の線。今から6時までの間に宿題が終わる"><line x1="10" y1="62" x2="230" y2="62" class="ax"/><path d="M223 57 L230 62 L223 67" class="ax"/><line x1="30" y1="54" x2="30" y2="70" class="ax"/><circle cx="120" cy="62" r="4" class="pt"/><line x1="190" y1="50" x2="190" y2="74" class="cv2"/><text x="24" y="46">今</text><text x="87" y="34">宿題が終わる</text><text x="160" y="46">6時(期限)</text><path d="M32 78 L188 78" class="dash"/><text x="55" y="96">この間のどこかで完了</text><text x="64" y="113">will have finished</text></svg>';
  var AUXSCALE = '<svg viewBox="0 0 240 120" class="lz-fig" role="img" aria-label="推量の助動詞の確信度。左ほど低く右ほど高い。can\'t、may・might、should、must の順"><line x1="10" y1="56" x2="230" y2="56" class="ax"/><path d="M223 51 L230 56 L223 61" class="ax"/><circle cx="24" cy="56" r="4" class="pt"/><circle cx="94" cy="56" r="4" class="pt"/><circle cx="156" cy="56" r="4" class="pt"/><circle cx="208" cy="56" r="4" class="pt"/><text x="12" y="40">can\'t</text><text x="4" y="78">はずがない</text><text x="62" y="40">may / might</text><text x="62" y="94">かもしれない</text><text x="138" y="40">should</text><text x="140" y="78">はずだ</text><text x="194" y="40">must</text><text x="180" y="94">ちがいない</text><text x="8" y="112">← 確信が低い</text><text x="150" y="112">確信が高い →</text></svg>';

  // ===== 文型 =====
  L.e_h1 = {
    goal: '英文を S(主語)・V(動詞)・O(目的語)・C(補語)に分けて、5つの文型のどれかを見分けられるようになる。',
    intro: '英語は、日本語とちがって【語順が意味を決める】言葉です。「Ken loves Mary.」と「Mary loves Ken.」は単語が同じでも意味が逆になります。どんなに長い英文も、骨組みは5つの型(5文型)のどれかです。骨組みが取れれば、長い文も迷わず読めるようになります。',
    pre: 'まず【品詞】をおさらいします。英単語は、はたらきによって、名詞(人や物の名前:book、Ken)、動詞(動作や状態:run、is)、形容詞(名詞のようすを表す:happy、big)、副詞(動詞や形容詞などをくわしくする:very、fast、yesterday)などに分けられます。\n中学で習ったように、動詞には【be動詞】(am・is・are・was・were)と【一般動詞】(play、like など)があります。英語の文には、時制をもつ動詞が必ず1つあります。\n【前置詞】(in、on、at、to、for など)は名詞の前に置いて、場所や時などを表すかたまりを作ります。in the park(公園で)のように、「前置詞+名詞」で1つのかたまりと考えます。\n日本語は「私は本を読む」を「本を私は読む」と言いかえても通じますが、英語の I read a book. は語順を変えられません。この「語順が大事」という感覚をもって読み進めましょう。',
    secs: [
      { h: '文の要素は4つ+おまけ', t: '英文の骨組みをつくる要素は、S・V・O・C の4つです。まずは、それぞれが何なのかを1つずつ確認しましょう。\n【S(主語)】は「〜は・〜が」にあたる語で、名詞や代名詞がなります。【V(動詞)】は「〜する・〜である」にあたる語で、どの英文にも必ずあります。\n【O(目的語)】は動詞の動作を受ける相手で、「〜を・〜に」にあたる名詞です。【C(補語)】は、S や O が「どんなものか・どんな状態か」を説明する語で、名詞か形容詞がなります。\nこのほかの語、つまり場所・時・様子などを表す語句は【M(修飾語)】と呼び、文型には数えません。in the park、yesterday、very などが M です。\nなぜ M を数えないのでしょうか。それは、M は取り除いても文が成り立つ「飾り」だからです。I play tennis (in the park). から in the park を消しても、I play tennis. で文は完成します。\n文型を考えるときは、まず M をかっこでくくって消し、残った S・V・O・C を見ます。',
        key: 'M(修飾語)をかっこでくくって消し、残った S・V・O・C の並び方で文型を決めます。' },
      { h: '第1文型 SV と 第2文型 SVC', t: '【第1文型 SV】は、S と V だけで文が完成する形です。例:Birds fly.(鳥は飛ぶ)/My father works (in a bank).(父は銀行で働いている)→ in a bank は M です。\n【第2文型 SVC】は、V の後ろに、S を説明する C がくる形です。【S=C】の関係が成り立つのが目印です。\n例:She is a doctor.(彼女は医者だ)→ She=a doctor。例:He looks happy.(彼はうれしそうに見える)→ He=happy。\nSVC をとる主な動詞は、be、become・get・grow・turn(〜になる)、look・seem(〜に見える・思われる)、sound(〜に聞こえる)、feel(〜に感じる)、keep・remain(〜のままである)です。\nC には形容詞か名詞が入ります。He looks happily. とはしません。副詞は名詞のようすを説明できないので、C になれないからです。',
        key: 'SVC は「S=C」が成り立つ形。C になれるのは形容詞と名詞で、副詞はなれません。',
        ex: [{ q: '次の2文の文型を答え、和訳しよう。\n(1) The leaves turned red.\n(2) He turned the key.', hint: 'V の後ろの語と S の間に「=」が成り立つかを考えます。', steps: ['(1) S=The leaves、V=turned。後ろの red は形容詞で、「The leaves are red(葉が赤い)」と S=C の関係が成り立つ。', '(1) よって SVC。turn はここでは「〜になる」の意味。', '(2) S=He、V=turned。「He is the key」は成り立たないので、the key は C ではなく、動作を受ける O。', '(2) よって SVO。turn はここでは「〜を回す」の意味。'], a: '(1) SVC:葉が赤くなった。(2) SVO:彼はかぎを回した。', check: '同じ turn でも文型によって意味が変わります。和訳が自然な日本語になるかで確かめます。' }] },
      { h: '第3文型 SVO と 第4文型 SVOO', t: '【第3文型 SVO】は、V の後ろに動作の相手 O が1つくる形で、S≠O です。例:I love music.(私は音楽が大好きだ)→ S=I、V=love、O=music。\n【第4文型 SVOO】は「(人)に(物)を〜する」という形で、O が2つ並びます。例:He gave me a book.(彼は私に本をくれた)→ O₁=me、O₂=a book で、me≠a book です。\nSVOO は、前置詞を使って SVO に書きかえられます。そのとき、動詞によって to を使うか for を使うかが決まっています。\ngive・show・tell・send・lend などは【to】を使います。これらは、相手がいないと成り立たない「相手に届く」動作だからです。例:He gave a book to me.\nbuy・make・cook・find などは【for】を使います。これらは相手がいなくても自分だけでできる動作で、「〜のために」してあげる、という意味になるからです。例:She bought a bag for me.',
        key: 'SVOO を SVO に書きかえるときは、相手が必要な動作なら to、自分だけでできる動作なら for を使います。',
        ex: [{ q: '前置詞を使って SVO の文に書きかえよう。\n(1) She showed me her photos.\n(2) My uncle bought me a watch.', hint: '動詞が「相手に届く動作」か「自分だけでもできる動作」かを考えます。', steps: ['(1) show(見せる)は、見る相手がいないと成り立たない動作なので to を使う。', '(1) 物(her photos)を先に置き、to + 人(me)を後ろに回す。', '(2) buy(買う)は、相手がいなくても自分だけでできる動作なので for を使う。', '(2) 物(a watch)を先に置き、for + 人(me)を後ろに回す。'], a: '(1) She showed her photos to me.(彼女は私に写真を見せてくれた)(2) My uncle bought a watch for me.(おじは私に腕時計を買ってくれた)', check: '書きかえた文から to me・for me を外すと、S + V + O の文として成り立つことを確かめます。' }] },
      { h: '第5文型 SVOC', t: '【第5文型 SVOC】は、O の後ろに、O を説明する C がくる形です。【O=C】の関係(O is C)が成り立つのが目印です。\n例:The news made her happy.(その知らせは彼女を喜ばせた)→ she is happy。例:We call him Ken.(私たちは彼をケンと呼ぶ)→ he is Ken。\n例:I found the book easy.(その本はやさしいとわかった)→ the book is easy。\nSVOC をとる主な動詞は、make(O を C にする)、keep・leave(O を C のままにしておく)、call・name(O を C と呼ぶ・名づける)、find・think(O が C だとわかる・思う)です。\n【SVOO と SVOC の見分け方】O の後ろの2語の間に be動詞を入れてみます。「O is ○○」が成り立てば SVOC、成り立たなければ SVOO です。',
        key: 'O の後ろに be動詞を入れて「O is ○○」が成り立てば SVOC、成り立たなければ SVOO です。',
        ex: [{ q: '次の2文の文型を答え、和訳しよう。\n(1) My mother made me a cake.\n(2) My mother made me angry.', hint: 'me の後ろの語との間に be動詞を入れてみます。', steps: ['(1) S=My mother、V=made。me と a cake の間に be を入れると「I am a cake」となり、意味が通らないので me≠a cake。', '(1) O が2つ並ぶ SVOO。make はここでは「(人)に(物)を作る」の意味。', '(2) me と angry の間に be を入れると「I am angry」となり、意味が通るので O=C。', '(2) SVOC。make はここでは「O を C にする」の意味。'], a: '(1) SVOO:母は私にケーキを作ってくれた。(2) SVOC:母は私を怒らせた。', check: '(1) は My mother made a cake for me. と書きかえられますが、(2) は書きかえられないことでも区別できます。' }] },
      { h: '自動詞と他動詞', t: 'O をとらない動詞を【自動詞】、O をとる動詞を【他動詞】といいます。同じ動詞でも、意味によってどちらにもなるものが多くあります(run は「走る」なら自動詞、「〜を経営する」なら他動詞)。\n日本語の「〜について」「〜と」につられて前置詞をつけると、まちがえる他動詞があります。discuss the plan(× discuss about)、marry him(× marry with)、enter the room(× enter into)、reach the station(× reach to)、approach the town(× approach to)です。\n形がまぎらわしいのが lie と lay です。【lie】(横になる・ある/自動詞)は lie - lay - lain、【lay】(〜を置く・横たえる/他動詞)は lay - laid - laid と変化します。\n同じように、【rise】(上がる/自動詞)は rise - rose - risen、【raise】(〜を上げる/他動詞)は raise - raised - raised です。\nlie の過去形と lay の原形が同じ lay なので、特に注意します。迷ったら、後ろに O があるかを見ます。O があれば他動詞(lay・raise)です。',
        key: '後ろに O(〜を)があれば他動詞、なければ自動詞。discuss・marry・enter・reach は前置詞なしで O をとります。',
        ex: [{ q: '正しいほうを選ぼう。\n(1) We discussed (the problem / about the problem).\n(2) Please (raise / rise) your hand.', hint: 'その動詞が、すぐ後ろに O をとる他動詞かどうかを考えます。', steps: ['(1) discuss は「〜について話し合う」という意味の他動詞。「について」の意味まで動詞にふくまれているので、すぐ後ろに O をとり、about は不要。', '(2) 後ろに your hand という O がある → O をとる他動詞が必要。', 'rise は自動詞(O をとらない)、raise は他動詞(〜を上げる)なので raise。'], a: '(1) the problem(私たちはその問題について話し合った)(2) raise(手を挙げてください)', check: '(2) で rise を使うなら、The sun rises.(太陽がのぼる)のように後ろに O がない文になるはずです。' }] },
      { h: '長い文の文型をとる手順', t: '実際の英文は、M がたくさんついて長くなっています。でも、次の手順で進めれば、どんなに長い文でも骨組みが取れます。\n①前置詞+名詞のかたまり(in the park など)と、時・様子を表す副詞(yesterday、very など)をかっこでくくります。\n②残った語の中から、時制をもつ動詞(V)を探します。V の前にある名詞のかたまりが S です。\n③V の後ろに残った語を見ます。何もなければ SV、1つなら SVC か SVO(「S=○○」が成り立てば SVC)、2つなら SVOO か SVOC(「O is ○○」が成り立てば SVOC)です。\nS の中にも M があることに注意します。The boy (in the car) is my brother. の S は The boy で、in the car は The boy を説明する M です。',
        key: 'M をくくる → V を探す → V の前が S → V の後ろの語の数と「=」の関係で文型を決める、の順で進めます。',
        ex: [{ q: '文型を答え、和訳しよう。\nThe old man in the hat kept the door of his shop open all night.', hint: '前置詞のかたまり(in 〜、of 〜)と、時を表す語句をかっこでくくることから始めます。', steps: ['M をくくる:The old man (in the hat) kept the door (of his shop) open (all night)。in the hat・of his shop は前の名詞を説明する M、all night は時を表す M。', 'V は時制をもつ kept。その前の The old man が S。', 'kept の後ろに the door と open の2つが残る。「The door is open(ドアが開いている)」が成り立つので O=C。', 'よって SVOC。keep O C は「O を C のままにしておく」の意味。'], a: 'SVOC:帽子をかぶったその老人は、一晩中、店のドアを開けたままにしていた。', check: 'かっこの中を外した The old man kept the door open. だけでも、文として成り立つことを確かめます。' }] }
    ],
    faq: [
      ['なぜ文型を覚える必要があるの?', '文型が分かると、動詞の意味が決まるからです。たとえば make は、SVO なら「〜を作る」、SVOO なら「(人)に(物)を作ってあげる」、SVOC なら「O を C にする」と意味が変わります。\n長い英文でも、文型が取れれば「だれが・何を・どうした」の骨組みがすぐに見えます。'],
      ['There is 〜 の文は何文型になるの?', 'There is a book on the desk.(机の上に本がある)では、主語は a book です。There は文型に数えない語として扱い、V=is、S=a book、on the desk は M なので、第1文型 SV と考えるのが一般的です。'],
      ['O と C は、どう見分けるの?', 'S や O と「イコール」になるのが C、ならないのが O です。\nHe became a teacher.(He=a teacher なので C)と He met a teacher.(He≠a teacher なので O)のように、be動詞を入れて「=」が成り立つかで確かめます。']
    ],
    terms: [['S(主語)', '文の主題。「〜は・〜が」にあたる名詞'], ['V(動詞)', '「〜する・〜である」にあたる語。文に必ず1つある'], ['O(目的語)', '動作を受ける名詞。「〜を・〜に」'], ['C(補語)', 'S や O の正体・状態を説明する名詞・形容詞'], ['M(修飾語)', '文型に数えない飾りの語句(副詞・前置詞のかたまりなど)'], ['自動詞/他動詞', 'O をとらない動詞/O をとる動詞']],
    miss: ['He looks happily. のように、C に副詞を入れてしまう。C は S のようすを説明するので、形容詞か名詞にします。', 'in the park などの前置詞のかたまりを O だと思ってしまう。前置詞+名詞は M なので、最初にかっこでくくる習慣をつけます。', 'SVOO と SVOC を区別せず、made me a cake と made me angry を同じ意味で訳す。O の後ろに be動詞を入れて確かめます。', 'discuss about、enter into など、他動詞に余計な前置詞をつける。日本語の「〜について」につられないよう、前置詞なしの形で覚えます。'],
    sum: ['M をかっこでくくり、S・V・O・C だけを見る。', 'SVC は S=C、SVOC は O=C の関係が目印。', 'SVOO は「(人)に(物)を」。to か for で SVO に書きかえられる。', 'C になれるのは名詞と形容詞だけ。', '自動詞・他動詞は、前置詞の有無とセットで覚える。'],
    next: '次は「過去完了」に進みましょう。文の骨組みが取れるようになったら、動詞の「時」の表し方をくわしく学ぶと、出来事の順番まで正確に読めるようになります。'
  };

  // ===== 時制 =====
  L.e_pastperf = {
    goal: '過去完了(had+過去分詞)を、「過去のある時点より前」を表すときに正しく使えるようになる。',
    intro: '現在完了(have+過去分詞)は、「今」を基準にして、それまでの完了・経験・継続を表しました。【過去完了】は、その基準を「今」から【過去のある時点】に移したものです。「私が駅に着いたとき、電車はもう出てしまっていた」のように、過去の2つの出来事の順番をはっきりさせるときに使います。',
    pre: '【過去形】は、過去の出来事をそのまま表す形です。I visited Kyoto last year.(去年京都を訪れた)のように、yesterday、last 〜、〜 ago など過去の時を表す語と一緒に使えます。\n【過去分詞】は動詞の変化形の1つです。規則動詞は過去形と同じ -ed の形(visit - visited - visited)、不規則動詞は別の形(go - went - gone、see - saw - seen、eat - ate - eaten)になります。\n中学で習った【現在完了】は【have(has)+ 過去分詞】で、「今」を基準に、今までに〜してしまった(完了)、〜したことがある(経験)、ずっと〜している(継続)を表しました。例:I have lived here for three years.(私はここに3年住んでいる)\n現在完了のポイントは、過去のことと「今」がつながっていることでした。この単元では、その基準の「今」を「過去のある時点」に動かします。',
    secs: [
      { h: '形と基本のイメージ', t: '形は【had + 過去分詞】です。主語が何であっても had を使います。\n例:When I arrived at the station, the train had already left.(私が駅に着いたとき、電車はすでに出てしまっていた)\n「着いた(arrived)」が過去の基準点です。電車が出たのはそれよりも前なので、had left になります。\nなぜ過去形だけではいけないのでしょうか。When I arrived at the station, the train left. と過去形を2つ並べると、「私が着いたとき(ちょうど)電車が出た」という意味になり、出来事の前後関係が変わってしまうからです。\n時間の線で考えると、【大過去(had left)→ 過去(arrived)→ 現在】の順になります。過去完了は、必ず「基準になる過去」とセットで使います。', fig: PASTPERF,
        key: '過去完了 had + 過去分詞は、「過去のある時点」よりさらに前のことを表します。必ず基準になる過去とセットで使います。',
        ex: [{ q: '( ) に入る正しい形を選ぼう。\nBy the time we arrived, the concert ( ).\n① has started ② had started ③ starts ④ will start', hint: 'まず、基準になる時点(いつより前か)を探します。', steps: ['基準になる時点を探す:we arrived(私たちが着いた)は過去。', 'コンサートが始まったのは、到着より前のこと。', '「過去の時点より前」なので過去完了 had + 過去分詞を使う。', '現在完了 has started は「今」が基準なので、過去の基準点とは合わない。'], a: '② had started(私たちが着いたときには、コンサートは始まっていた)', check: '時間の線に「始まった → 着いた → 今」と並べ、始まったのが基準点より前になっていることを確かめます。' }] },
      { h: '過去完了の4つの用法', t: '現在完了と同じく、完了・経験・継続の意味があり、さらに「大過去」の用法があります。\n【完了・結果】過去の時点までに〜してしまっていた。例:The movie had already started when we got there.(私たちが着いたとき、映画はもう始まっていた)\n【経験】過去の時点までに〜したことがあった。例:I had never seen snow before I went to Hokkaido.(北海道に行くまで、雪を見たことがなかった)\n【継続】過去の時点まで(ずっと)〜していた。例:She had lived in Osaka for five years when she moved to Tokyo.(東京へ引っ越したとき、彼女は大阪に5年住んでいた)\n【大過去】過去の出来事より前に起きたことを表す。例:I lost the watch my father had given me.(父がくれた時計をなくした)→ くれたのは、なくすより前。\nどの用法かは、already・just(完了)、never・before・once・twice(経験)、for・since(継続)などの語が手がかりになります。この目印は現在完了と同じです。',
        key: '用法の目印は現在完了と同じです(already=完了、never・twice=経験、for・since=継続)。',
        ex: [{ q: '過去完了の用法を答え、和訳しよう。\n(1) I had visited Paris twice before I was twenty.\n(2) He had been sick for a week when he saw a doctor.', hint: 'twice、for a week のような目印の語に注目します。', steps: ['(1) 基準は「20歳になる前」という過去の時点。twice(2回)は回数を表すので経験。', '(2) 基準は「医者にみてもらったとき(saw a doctor)」。', '(2) for a week(1週間)は期間を表すので継続。had been sick=その時点までずっと病気だった。'], a: '(1) 経験:私は20歳になる前に、パリを2回訪れたことがあった。(2) 継続:彼は1週間具合が悪かったところで、医者にみてもらった。', check: '(2) は「医者にみてもらった時点で、病気が1週間続いていた」と言いかえられれば継続です。' }] },
      { h: '過去完了進行形', t: '過去のある時点まで、動作が【ずっと続いていた】ことを強調するときは、【had been + 〜ing】を使います。\n例:I had been waiting for an hour when she finally came.(彼女がやっと来たとき、私は1時間ずっと待っていた)\nwait、study、rain など、続けて行う動作に使います。\nknow、like のような状態を表す動詞はふつう進行形にしないので、had known のように過去完了の継続用法で表します。例:I had known him for ten years when he moved away.(彼が引っ越したとき、私は彼と知り合って10年だった)',
        ex: [{ q: '( ) 内の動詞を、過去完了進行形にして文を完成させ、和訳しよう。\nWhen I woke up, it ( rain ) for hours.', hint: '「目が覚めたとき」が基準の過去、「何時間も」が継続の目印です。', steps: ['基準の過去:When I woke up(目が覚めたとき)。', 'for hours(何時間も)とあり、雨は基準の時点まで降り続いていた。', 'rain は続けて起こる動作なので、進行形にできる → had been raining。'], a: 'had been raining(私が目を覚ましたとき、何時間も雨が降り続いていた)', check: 'had been の後ろが -ing 形になっているか、主語 it に関係なく had を使っているかを確かめます。' }] },
      { h: '過去完了を使わなくてよい場合', t: 'before・after など、出来事の順番が接続詞からはっきり分かるときは、過去形だけで書いてもかまいません。\n例:I went out after I finished my homework.(宿題を終えてから外出した)※ after I had finished と過去完了で書いても正しい文です。\nまた、起きた順番どおりに並べるときも過去形で十分です。例:I got up, washed my face, and left home.(起きて、顔を洗って、家を出た)\n過去完了が必要なのは、【書いた順番と起きた順番が逆になる】ときです。',
        key: '過去完了が必要なのは、書いた順番と起きた順番が逆になるときです。',
        ex: [{ q: '日本語に合うように、( ) の動詞を正しい形にしよう。\n「私は、前の晩に買った本を読んだ。」\nI read the book I ( buy ) the night before.', hint: '「読んだ」と「買った」のどちらが先に起きたかを考えます。', steps: ['基準の過去:read(読んだ)。この read は過去形。', '本を買ったのは、読むより前(前の晩)。', '文の中では「買った」が後ろに書かれていて、起きた順番と逆になるので、過去完了を使う。'], a: 'had bought', check: 'buy の過去分詞が bought であることと、the night before(その前の晩)が基準点より前を表していることを確かめます。' }] },
      { h: '現在完了・過去形・過去完了の使い分け', t: '3つの形は、【基準になる時点】がちがいます。現在完了は「今」、過去完了は「過去のある時点」が基準です。過去形は、過去の出来事を今と切り離して、そのまま表します。\nだから、yesterday・last week・〜 ago のような【はっきりした過去の時】は、現在完了と一緒に使えません。現在完了は「今」につながる形なので、今と切り離された時を表す語と合わないからです。× I have seen him yesterday. → ○ I saw him yesterday.\n一方、過去完了は、過去の基準点がある文で使います。例:He said that he had seen her the day before.(彼は、その前日に彼女に会ったと言った)→ 基準点は said です。\nまた、伝える動詞が過去のときは、that 節の中の現在完了は過去完了になります(時制の一致)。例:She said, "I have lost my key." → She said that she had lost her key.(彼女は、かぎをなくしたと言った)\n迷ったら、「基準はどこか」を時間の線の上で確かめましょう。',
        key: '基準が今なら現在完了、基準が過去なら過去完了。はっきりした過去の時(yesterday・〜 ago)は過去形で表します。',
        ex: [{ q: '次の文の誤りを直そう。\n(1) I have finished my homework yesterday.\n(2) When I called him, he already went to bed.', hint: 'それぞれの文の「基準の時点」がどこかを考えます。', steps: ['(1) yesterday ははっきりした過去の時を表すので、今を基準にする現在完了とは使えない。', '(1) 過去形 finished に直す。', '(2) 基準は「電話したとき(called)」という過去の時点。彼が寝たのはそれより前。', '(2) already(すでに)もあり、過去の時点までの完了なので had already gone にする。'], a: '(1) I finished my homework yesterday.(昨日宿題を終えた)(2) When I called him, he had already gone to bed.(私が電話したとき、彼はもう寝てしまっていた)', check: '(2) を時間の線に並べると「寝た → 電話した → 今」の順になり、過去完了が基準点より前を表していることが確かめられます。' }] }
    ],
    faq: [
      ['過去完了と現在完了は、どうちがうの?', '「基準になる時点」がちがいます。現在完了は「今」まで、過去完了は「過去のある時点」までの完了・経験・継続を表します。\n形も、現在完了は have(has)、過去完了は主語に関係なく had です。'],
      ['過去の出来事が2つあれば、いつも片方を過去完了にするの?', 'いいえ。起きた順番どおりに書くときや、before・after で順番がはっきりしているときは、過去形だけで十分です。\n過去完了が必要なのは、後に書いたことが先に起きていて、順番を示さないと誤解されるときです。'],
      ['had had という形は正しいの?', '正しい形です。1つ目の had は過去完了を作る had、2つ目は have(持っている・食べる)の過去分詞の had です。\n例:I had already had breakfast when he came.(彼が来たとき、私はもう朝食を食べ終えていた)']
    ],
    terms: [['過去完了', 'had + 過去分詞。過去のある時点を基準にした完了・経験・継続'], ['大過去', '過去の出来事よりもさらに前に起きたことを表す用法'], ['過去完了進行形', 'had been 〜ing。過去の時点まで動作が続いていたことを表す'], ['基準点', '「いつより前か」を決める、文の中の過去の時点'], ['時制の一致', '主節の動詞が過去のとき、that 節などの動詞もそれに合わせて過去・過去完了にすること']],
    miss: ['基準になる過去がないのに、過去完了を使ってしまう。過去完了は過去の基準点とセットなので、まず基準点を探します。', '過去の基準点があるのに、現在完了(has + 過去分詞)を使ってしまう。現在完了の基準は「今」だと確認します。', 'yesterday、last week など、はっきり過去の時を表す語を現在完了と一緒に使う(I have seen him yesterday. は誤り)。', 'had の後ろを過去形にしてしまう(× had went → ○ had gone)。不規則動詞の過去分詞を3つの形でセットで覚えます。'],
    sum: ['過去完了 = had + 過去分詞。基準は「過去のある時点」。', '大過去 → 過去 → 現在 の順に時間の線にのせて考える。', '用法は 完了・経験・継続・大過去。目印の語は現在完了と同じ。', '動作の継続を強調するなら had been 〜ing。', '順番が接続詞で明らかなら、過去形だけでもよい。'],
    next: '次は「未来完了」です。過去完了の「基準を過去に移す」考え方を、今度は未来に当てはめるだけなので、続けて学ぶと理解しやすくなります。'
  };
  L.e_futperf = {
    goal: '未来完了(will have+過去分詞)を使って、「未来のある時点までに〜しているだろう」を表せるようになる。',
    intro: '「6時までには宿題を終えているだろう」「来年で、ここに住んで10年になる」。このように、【未来のある時点】を基準にして、それまでの完了・経験・継続を言うのが【未来完了】です。過去完了の基準を、今度は未来に移したものと考えると分かりやすくなります。',
    pre: '【will + 動詞の原形】は「〜するだろう・〜するつもりだ」と、未来のことを表す形です。will の後ろは、主語が何であっても必ず原形になります(× He will goes.)。\n【現在完了(have + 過去分詞)】は「今」までの完了・経験・継続を、【過去完了(had + 過去分詞)】は「過去のある時点」までの完了・経験・継続を表しました。\n2つに共通するのは、「基準になる時点を1つ決め、その時点までに何が起きたかを表す」ことです。基準が今なら現在完了、過去なら過去完了でした。\nこの単元では、その基準を「未来のある時点」に置きます。形は、will と have + 過去分詞を組み合わせるだけです。',
    secs: [
      { h: '形と基本のイメージ', t: '形は【will have + 過去分詞】です。主語が3人称単数でも has にはなりません。will の後ろは原形なので have です。\n例:I will have finished my homework by six.(6時までには宿題を終えているだろう)\n基準は「6時」という未来の時点です。今から6時までのどこかで、宿題が終わります。\nなぜ will finish だけではだめなのでしょうか。I will finish my homework at six. は「6時に終える」という動作、I will have finished my homework by six. は「6時の時点ではもう終わっている」という状態を表し、言いたいことがちがうからです。\n目印になるのは【by + 未来の時点】(〜までには)や【by the time 〜】(〜するころまでには)です。', fig: FUTPERF,
        key: '未来完了 will have + 過去分詞は、「未来のある時点では、もう〜している」を表します。目印は by 〜・by the time 〜 です。',
        ex: [{ q: '( ) に入る正しい形を選ぼう。\nI ( ) this book by the end of this week.\n① will have read ② have read ③ had read ④ read', hint: 'by the end of this week が、未来・過去・今のどれを基準にしているかを考えます。', steps: ['by the end of this week=今週末までに。これは未来の基準点。', '未来の時点までの完了なので、will have + 過去分詞を使う。', 'had read は過去の基準点、have read は今の基準点が必要なので合わない。'], a: '① will have read(今週末までには、この本を読み終えているだろう)', check: '「今 → 読み終える → 今週末」と時間の線に並べ、基準点が未来にあることを確かめます。' }] },
      { h: '完了・経験・継続', t: '【完了】未来の時点までに〜してしまっているだろう。例:The train will have left by the time we get to the station.(私たちが駅に着くころには、電車は出てしまっているだろう)\n【経験】未来の時点で〜したことになる。例:If I see this movie again, I will have seen it three times.(この映画をもう一度見たら、3回見たことになる)\n【継続】未来の時点まで(ずっと)〜していることになる。例:By next year, I will have lived here for ten years.(来年で、ここに住んで10年になる)\n動作が続いていることを強調するときは、【will have been 〜ing】(未来完了進行形)を使います。例:By five o\'clock, I will have been studying for three hours.(5時で、3時間ずっと勉強していることになる)\n用法の目印は、現在完了・過去完了と同じです(回数=経験、for 〜=継続)。',
        ex: [{ q: '和訳しよう。\nBy next April, my brother will have worked at the company for twenty years.', hint: 'By next April が基準点、for twenty years が用法の目印です。', steps: ['By next April=来年の4月までに(未来の基準点)。', 'will have worked ... for twenty years=未来完了の継続。', '「その時点で20年働いたことになる」と訳す。'], a: '来年の4月で、兄はその会社に20年勤めたことになる。', check: '「来年の4月の時点で、勤めた期間が20年に達する」と言いかえて、意味がずれていないか確かめます。' }] },
      { h: 'by と until のちがい', t: '【by】は「〜までに」(期限)です。その時点までに1回終わればよい、という意味で、未来完了とよく一緒に使います。\n【until(till)】は「〜までずっと」(継続)です。その時点まで、同じ状態や動作が続きます。\n例:I will wait here until six.(6時までずっとここで待つ)/I will have finished it by six.(6時までには終えているだろう)\n迷ったら、日本語で「〜までに」と言えるなら by、「〜までずっと」と言えるなら until と考えます。',
        key: 'by=〜までに(期限)、until=〜までずっと(継続)。',
        ex: [{ q: '( ) に by か until を入れよう。\n(1) I will stay here ( ) Sunday.\n(2) Please return the book ( ) Friday.', hint: '「〜までずっと」か「〜までに」か、日本語にして考えます。', steps: ['(1) stay(とどまる)は日曜日まで続く状態 →「日曜日までずっと」なので until。', '(2) return(返す)は1回すれば終わる動作 →「金曜日までに」という期限なので by。', '日本語にして意味が自然かを確かめる。'], a: '(1) until(日曜日までずっとここにいます)(2) by(金曜日までに本を返してください)', check: '(2) を until にすると「金曜日までずっと返し続ける」という不自然な意味になることでも確かめられます。' }] },
      { h: 'by the time の中は現在形', t: 'by the time(〜するころまでには)や when の後ろは、「いつ」を表す【時の副詞節】です。\n英語では、時の副詞節の中は、未来のことでも【現在形】で表す決まりがあります。未来であることは、主節の will で十分伝わるからです。\n× By the time he will come, … → ○ By the time he comes, I will have cleaned the room.(彼が来るころには、部屋を掃除し終えているだろう)\nつまり、未来完了の文では、主節は will have + 過去分詞、by the time の中は現在形、という組み合わせになります。',
        key: 'by the time・when の中は、未来のことでも現在形。will を使うのは主節だけです。',
        ex: [{ q: '( ) 内の動詞を正しい形にしよう。\nBy the time you ( come ) back, I ( finish ) cleaning the kitchen.', hint: 'by the time の中と主節で、使う形がちがいます。', steps: ['by the time 〜 は時の副詞節 → 未来のことでも現在形。主語 you なので come。', '主節は「あなたが戻るころまでには」という未来の基準点までの完了。', 'よって will have + 過去分詞 → will have finished。'], a: 'come / will have finished(あなたが戻るころまでには、台所の掃除を終えているでしょう)', check: 'will が主節だけに入っていて、by the time の中には入っていないことを確かめます。' }] },
      { h: '3つの完了形をまとめる', t: '完了形は3つとも「基準の時点までに何が起きたか」を表します。ちがうのは基準の位置だけです。\n基準が今=【have(has)+ 過去分詞】、基準が過去=【had + 過去分詞】、基準が未来=【will have + 過去分詞】です。\n基準になる未来の時点がない文では、未来完了はふつう使いません。I will have finished it. だけでは「いつまでに」が分からないので、by 〜 などで時点を示すか、文脈で時点が分かっている必要があります。\nただ未来の予定を言うだけなら、will + 原形で十分です。例:I will visit Kyoto next week.(来週京都を訪れる予定だ)\n完了形を選ぶときは、まず「基準の時点」を文の中から見つけることが決め手になります。',
        key: '完了形は基準の位置で決まる:今=have + 過去分詞、過去=had + 過去分詞、未来=will have + 過去分詞。',
        ex: [{ q: '( ) に入る最も適切なものを選ぼう。\nMy parents ( ) married for twenty-five years next month.\n① will be ② have been ③ will have been ④ had been', hint: 'next month が基準点、for twenty-five years が用法の目印です。', steps: ['基準の時点は next month(来月)で、未来。', 'for twenty-five years(25年間)は継続の目印。be married は「結婚している」状態。', '未来の時点までの継続なので will have + 過去分詞 → will have been。', '② は今が基準、④ は過去が基準なので next month と合わない。'], a: '③ will have been(来月で、両親は結婚して25年になる)', check: '「来月の時点で、結婚している期間が25年に達する」と言いかえて、意味が通るか確かめます。' }] }
    ],
    faq: [
      ['will have finished と will finish は、どうちがうの?', 'will finish は「(その時に)終える」という動作そのもの、will have finished は「(その時点では)もう終わっている」という状態を表します。\n「6時までには」と期限までに終わっていることを言いたいときは、未来完了がぴったりです。'],
      ['by the time の中に will を入れてはいけないのはなぜ?', 'by the time 〜 は「〜するころまでに」と時を表す副詞節だからです。英語では、時・条件の副詞節の中は、未来のことでも現在形で表す決まりがあります。\nくわしくは、次の「時・条件の副詞節」の単元で学びます。'],
      ['未来完了は実際によく使うの?', '会話ではそれほど多くありませんが、予定・計画の説明や、ニュース・長文の中ではよく使われます。入試では、by 〜 や by the time 〜 と組み合わせた文法問題としてよく出ます。']
    ],
    terms: [['未来完了', 'will have + 過去分詞。未来のある時点を基準にした完了・経験・継続'], ['未来完了進行形', 'will have been 〜ing。未来の時点まで動作が続いていることを表す'], ['by', '〜までに(期限)。1回終わればよい'], ['until', '〜までずっと(継続)'], ['時の副詞節', 'when・by the time などで始まり「いつ」を表す節。中は未来でも現在形']],
    miss: ['主語が he・she なので will has としてしまう。will の後ろは必ず原形 have です。', 'by と until を混同する。「〜までに」なら by、「〜までずっと」なら until と日本語で確かめます。', 'By the time he will come のように、時を表す副詞節の中に will を入れる。will は主節だけに入れます。', 'for 〜(期間)を見ただけで現在完了にしてしまう。next year など基準が未来なら will have + 過去分詞です。'],
    sum: ['未来完了 = will have + 過去分詞。', '目印は by + 未来の時点、by the time 〜。', '用法は 完了・経験・継続。継続の強調は will have been 〜ing。', 'by=〜までに、until=〜までずっと。', 'by the time・when の中は、未来のことでも現在形。'],
    next: '次は「時・条件の副詞節(時制)」です。by the time の中で現在形を使う決まりを、when・if・as soon as などにも広げて整理できます。'
  };
  L.e_tense = {
    goal: '時・条件を表す接続詞の後ろで、未来のことでも現在形を使う理由が分かり、名詞節の if・when と見分けられるようになる。',
    intro: '「明日雨が降ったら、家にいます」を英語にすると、If it rains tomorrow, I will stay home. です。tomorrow なのに will rain ではなく rains です。これは英語の決まりで、【時・条件を表す副詞節の中では、未来のことも現在形で表す】からです。ところが同じ if でも、will を使う場合があります。この単元では、その見分け方を身につけます。',
    pre: '【節】とは、S と V をふくむ語のかたまりのことです。if it rains には it(S)と rains(V)があるので節です。in the morning のように S と V がないかたまりは【句】といいます。\n1つの文に節が2つあるとき、文の中心になる節を【主節】、接続詞などで始まって主節にくっつく節を【従属節】といいます。If it rains, I will stay home. では、I will stay home が主節です。\n従属節は、文の中でのはたらきによって、名詞節(S・O・C になる)、形容詞節(名詞を説明する)、副詞節(「いつ・どんな条件で」などを加える)に分かれます。\nまた、ふつう未来のことは【will + 原形】で表します。I will call you tomorrow.(明日電話します)。この単元では、この will を「使わない」場所を学びます。',
    secs: [
      { h: '時・条件の副詞節は「現在形」', t: '次の接続詞が作る節は、文の中で「いつ・どんな条件で」を表す【副詞節】です。\n時:when(〜するとき)、before(〜する前に)、after(〜した後で)、until(〜するまで)、as soon as(〜するとすぐに)、by the time(〜するころまでに)\n条件:if(もし〜なら)、unless(〜しない限り)、once(いったん〜すれば)、in case(〜するといけないから)\nこれらの節の中では、【未来のことでも現在形】を使います。例:I will call you when I arrive at the station.(駅に着いたら電話します)\n例:If it is sunny tomorrow, we will go on a picnic.(明日晴れたら、ピクニックに行きます)\n未来であることは、主節の will や tomorrow で十分伝わるので、副詞節では現在形にする、と考えるとよいでしょう。',
        key: '時・条件を表す副詞節(when・if・before・until・as soon as など)の中は、未来のことでも現在形にします。',
        ex: [{ q: '( ) に入る正しい形を選ぼう。\nIf you ( ) any questions, please ask me.\n① have ② will have', hint: 'if 節が「もし〜なら」という条件を表しているかを確かめます。', steps: ['if 節は「もし質問があれば」という条件を表す。', 'if 以下を取り除いても Please ask me. で文が成り立つので、副詞節。', '条件の副詞節の中は、未来のことでも現在形 → have。'], a: '① have(何か質問があれば、私にたずねてください)', check: 'if 節を取り除いても主節だけで文として完成していることを、もう一度確かめます。' }] },
      { h: '完了の意味なら現在完了', t: '副詞節の中で「〜し終えたら」と完了の意味を表したいときは、未来完了(will have + 過去分詞)ではなく、【現在完了】を使います。\n未来完了も will をふくむ形なので、副詞節の中には入れられない、と考えます。\n例:I will lend you this book when I have finished reading it.(読み終えたら、この本を貸してあげます)\n例:You can go out after you have done your homework.(宿題をしてしまったら、出かけていいですよ)',
        ex: [{ q: '( ) 内の動詞を正しい形にしよう。\n(1) I will wait here until he ( come ) back.\n(2) I will give you this magazine when I ( read ) it.(読み終えたら)', hint: 'until・when はどちらも時の副詞節を作ります。', steps: ['(1) until(〜するまで)は時の副詞節 → 未来のことでも現在形。主語 he は3人称単数なので comes。', '(2) when も時の副詞節。「読み終えたら」と完了の意味なので、will have read ではなく現在完了を使う。', '(2) read の過去分詞は read(発音は「レッド」)。主語 I なので have read。'], a: '(1) comes(彼が戻るまでここで待ちます)(2) have read(読み終えたら、この雑誌をあげます)', check: 'どちらも副詞節の中に will が入っていないことを確かめます。' }] },
      { h: '名詞節の if・when は「will」を使う', t: 'if が「【〜かどうか】」、when が「【いつ〜するか】」という意味のときは、節が動詞の目的語(名詞のはたらき)になっています。これを【名詞節】といいます。名詞節の中では、未来のことは will で表します。\n例:I don\'t know if it will rain tomorrow.(明日雨が降るかどうか分からない)→ if 節は know の目的語\n例:Please tell me when he will come back.(彼がいつ戻ってくるか教えてください)→ when 節は tell の目的語\n【見分け方】if 節・when 節を取り除いてみます。\n取り除いても文が成り立つなら副詞節(現在形)です。例:I will stay home (if it rains tomorrow). → I will stay home. で完成。\n取り除くと文が成り立たないなら名詞節(will)です。例:I don\'t know (if it will rain). → I don\'t know. だけでは「何を?」が欠けて不完全です。',
        key: '節を取り除いても文が成り立つなら副詞節(現在形)、成り立たないなら名詞節(未来は will)です。',
        ex: [{ q: '( ) に入る正しい形を選ぼう。\n(1) Let\'s start the meeting as soon as he ( ). ① comes ② will come\n(2) I wonder if he ( ) to the party next week. ① comes ② will come', hint: 'as soon as 節・if 節を取り除いて、残りが文として完成するかを見ます。', steps: ['(1) as soon as は「〜するとすぐに」という時の副詞節。取り除いても Let\'s start the meeting. で文が成り立つ。', '(1) 副詞節なので、未来のことでも現在形 comes。', '(2) if 節は wonder(〜かしらと思う)の目的語で「〜かどうか」の名詞節。取り除くと I wonder. だけで内容が欠ける。', '(2) 名詞節なので、未来のことは will で表す。'], a: '(1) ① comes(彼が来たらすぐに会議を始めよう)(2) ② will come(彼は来週パーティーに来るだろうか)', check: '(2) の if を whether(〜かどうか)に置きかえても意味が通れば、名詞節だと確かめられます。' }] },
      { h: '形容詞節の when にも注意', t: '名詞の後ろについて、その名詞を説明する when(関係副詞)の節も、副詞節ではありません。この場合も、未来のことは will で表します。\n例:I\'m looking forward to the day when you will visit us.(あなたが訪ねてくれる日を楽しみにしています)→ when 節は the day を説明する形容詞節\nまとめると、「未来でも現在形にする」のは【時・条件を表す副詞節】だけです。\nif・when を見たら、まず節のはたらき(副詞・名詞・形容詞のどれか)を確認する習慣をつけましょう。' },
      { h: 'unless・in case・once に注意', t: 'if・when 以外にも、時・条件を表す接続詞はたくさんあります。どれも副詞節を作るので、中は現在形です。\n【unless】は「〜しない限り」で、それ自体に否定の意味がふくまれています。例:I will go out unless it rains.(雨が降らない限り出かける)= if it doesn\'t rain。\nunless の後ろにさらに not をつけると、意味が逆になってしまうので注意します。\n【in case】は「〜するといけないから・〜する場合に備えて」です。例:Take an umbrella in case it rains.(雨が降るといけないから、かさを持っていきなさい)\n【once】は「いったん〜すれば」です。例:Once you learn to ride a bike, you will never forget how to do it.(いったん自転車に乗れるようになれば、乗り方は決して忘れない)',
        key: 'unless=if 〜 not。unless の後ろに not を重ねないように注意します。',
        ex: [{ q: '和訳しよう。\nYou will miss the bus unless you leave now.', hint: 'unless を「if 〜 not」に置きかえて考えます。', steps: ['unless you leave now = if you don\'t leave now(今出発しなければ)。', '主節:You will miss the bus(あなたはバスに乗り遅れるだろう)。', '条件 → 結果の順につなげて訳す。'], a: '今出発しないと、あなたはバスに乗り遅れますよ。', check: 'If you don\'t leave now, you will miss the bus. と書きかえても同じ意味になることを確かめます。' }] },
      { h: '節のはたらきを見分ける手順', t: 'if・when を見たら、次の順に確かめます。\n①その節を取り除いて、残りが文として完成するかを見ます。完成するなら副詞節です。\n②完成しない場合は、その節が動詞の目的語(〜かどうか・いつ〜か)になっていないかを見ます。know・ask・wonder・tell の後ろによく来ます。なっていれば名詞節です。\n③節の前に名詞(the day・the time など)があり、その名詞を説明していれば形容詞節です。\n副詞節なら未来でも現在形、名詞節・形容詞節なら未来は will で表します。',
        key: '副詞節だけが「未来でも現在形」。名詞節・形容詞節では、未来は will で表します。',
        ex: [{ q: '( ) 内の動詞を正しい形にしよう。\n(1) Nobody knows when the next earthquake ( happen ).\n(2) When the next earthquake ( happen ), we should stay calm.', hint: '同じ when でも、節のはたらきがちがいます。', steps: ['(1) when 節を取り除くと Nobody knows. で「何を?」が欠ける → knows の目的語の名詞節(いつ〜か)。', '(1) 名詞節なので、未来のことは will で表す → will happen。', '(2) When 節を取り除いても we should stay calm. で文が成り立つ → 時の副詞節(〜するとき)。', '(2) 副詞節なので現在形。主語は3人称単数なので happens。'], a: '(1) will happen(次の地震がいつ起きるか、だれにも分からない)(2) happens(次の地震が起きたときには、落ち着いて行動するべきだ)', check: '(1) は「いつ〜か」、(2) は「〜するとき」と訳せることで、節のはたらきのちがいが確かめられます。' }] }
    ],
    faq: [
      ['なぜ副詞節では、未来のことでも現在形なの?', 'まずは英語の決まりとして覚えるのが基本です。考え方としては、主節の will や tomorrow で未来であることは十分伝わるので、副詞節では「〜という時・条件が成り立てば」と現在形で表す、と理解するとよいでしょう。'],
      ['if 節の中に will が入ることは絶対にないの?', '「〜かどうか」の名詞節なら will を使います。また、副詞節でも、will が「〜する意志がある・〜してくれる」の意味のときは使うことがあります。例:If you will help me, I will be grateful.(手伝っていただけるなら、ありがたいです)\nただし、入試の基本問題では「条件の副詞節=現在形」で判断して問題ありません。'],
      ['when が「いつ」か「〜とき」か、どう見分けるの?', '節を取り除いて文が成り立てば「〜とき」(副詞節)、成り立たなければ「いつ〜か」(名詞節)です。\nTell me when he will come back. は、when 以下を取ると「何を教えるのか」が欠けるので名詞節です。']
    ],
    terms: [['節', 'S と V をふくむ語のかたまり'], ['副詞節', '文の中で「いつ・どんな条件で」などを表す節。取り除いても文が成り立つ'], ['名詞節', '文の中で S・O・C になる節。「〜かどうか」の if、「いつ〜か」の when など'], ['形容詞節', '前の名詞を説明する節(the day when 〜 など)'], ['主節', '文の中心になる節(If it rains, I will stay home. の I will stay home)'], ['unless', '〜しない限り(= if 〜 not)']],
    miss: ['If it will rain tomorrow, … と、条件の副詞節に will を入れてしまう。if を見たら、まず節を取り除いて副詞節かを確かめます。', '「〜かどうか」の if まで現在形にして、I don\'t know if he comes tomorrow. としてしまう。名詞節なら will です。', 'unless(〜しない限り)の後ろに not を重ねて、意味を逆にしてしまう。unless=if 〜 not と置きかえて確かめます。', 'once・in case・by the time が時・条件の副詞節を作ることに気づかず、中に will を入れてしまう。'],
    sum: ['時・条件の副詞節(when・if・before・until・as soon as など)は、未来でも現在形。', '「〜し終えたら」は現在完了で表す。', '「〜かどうか」の if、「いつ〜か」の when は名詞節なので will。', '名詞を説明する when(形容詞節)も will。', '見分けは、節を取り除いて文が成り立つかどうか。'],
    next: '次は「助動詞」です。will 以外の助動詞(must・may・should など)を使うと、話し手の確信の強さや、過去への後悔まで表せるようになります。'
  };

  // ===== 助動詞 =====
  L.e_aux = {
    goal: '助動詞を使って「〜にちがいない」「〜したはずがない」「〜すべきだったのに」などの推量・後悔を表し、SVOO・SVOC の受動態も作れるようになる。',
    intro: '助動詞には、「〜できる」「〜しなければならない」のような意味のほかに、話し手が【どのくらい確信しているか】を表すはたらきがあります。「彼は疲れているにちがいない」「疲れているかもしれない」「疲れているはずがない」。英語では must・may・can\'t を使い分けます。さらに「助動詞 + have + 過去分詞」にすると、過去のことへの推量や後悔を表せます。',
    pre: '【助動詞】は、動詞の前に置いて意味をそえる語です。中学では can(〜できる)、will(〜だろう)、must(〜しなければならない)、may(〜してもよい)、should(〜すべきだ)を習いました。\n助動詞の後ろは、主語や時制に関係なく、必ず【動詞の原形】です。He can swim.(× He can swims.)\n否定文は助動詞の後ろに not を置き(can\'t、must not)、疑問文は助動詞を主語の前に出します(Can you swim?)。\n【受動態】は【be動詞 + 過去分詞】で「〜される」を表す形でした。例:This room is cleaned every day.(この部屋は毎日掃除される)。能動態の O が、受動態では主語になります。',
    secs: [
      { h: '推量の助動詞と確信の強さ', t: '助動詞は、「〜にちがいない」から「〜のはずがない」まで、話し手の確信の強さを表し分けます。\n【must】〜にちがいない(ほぼ確実)。例:He must be tired after the long trip.(長旅の後だから、彼は疲れているにちがいない)\n【should / ought to】(当然)〜のはずだ。例:The bus should arrive soon.(バスはもうすぐ着くはずだ)\n【may / might】〜かもしれない(五分五分くらい。might のほうが少し弱い)。例:It may rain this afternoon.(午後は雨が降るかもしれない)\n【can\'t / cannot】〜のはずがない(must の反対)。例:That can\'t be true.(それが本当のはずがない)\n注意:must の反対は must not ではありません。must not は「〜してはいけない」(禁止)の意味になります。「〜のはずがない」は can\'t を使います。', fig: AUXSCALE,
        key: '確信の強さは must > should > may・might。「〜のはずがない」は must not ではなく can\'t です。',
        ex: [{ q: '( ) に must か can\'t を入れよう。\n(1) He has eaten nothing since this morning. He ( ) be hungry.\n(2) I saw her in Tokyo an hour ago. She ( ) be in Osaka now.', hint: '前の文が、後ろの推量の「根拠」になっています。', steps: ['(1) 朝から何も食べていない → おなかがすいていることはほぼ確実。', '(1) 「〜にちがいない」なので must。', '(2) 1時間前に東京で見た → 今、大阪にいることはありえない(移動に時間がかかる)。', '(2) 「〜のはずがない」なので can\'t。'], a: '(1) must(彼は朝から何も食べていない。おなかがすいているにちがいない)(2) can\'t(1時間前に東京で彼女を見た。彼女が今大阪にいるはずがない)', check: '(2) に must not を入れると「大阪にいてはいけない」という禁止の意味になり、文脈に合わないことを確かめます。' }] },
      { h: '助動詞 + have + 過去分詞(過去への推量)', t: '過去のことを推量するときは、助動詞の後ろを【have + 過去分詞】にします。助動詞の後ろは原形しか置けないので、「過去」の意味は have + 過去分詞で表すのです。\n【must have + 過去分詞】〜したにちがいない。例:She must have left her umbrella on the train.(彼女は電車にかさを置き忘れたにちがいない)\n【may (might) have + 過去分詞】〜したかもしれない。例:He may have missed the bus.(彼はバスに乗り遅れたのかもしれない)\n【can\'t (couldn\'t) have + 過去分詞】〜したはずがない。例:Ken can\'t have said such a thing.(ケンがそんなことを言ったはずがない)\n推量しているのは「今」で、推量している内容が「過去」です。だから助動詞そのものは過去形にしなくてかまいません。',
        key: '過去のことへの推量は「助動詞 + have + 過去分詞」。助動詞の後ろに過去形を置くことはできません。',
        ex: [{ q: '日本語に合うように、( ) に適語を入れよう。\n「彼の家の電気が消えている。彼は出かけたにちがいない。」\nThe lights in his house are off. He ( ) ( ) ( ) out.', hint: '「〜にちがいない」+「過去のこと」の組み合わせです。', steps: ['「〜にちがいない」→ must。', '「出かけた」は過去のこと → must の後ろを have + 過去分詞にする。', 'go の過去分詞は gone(go - went - gone)。'], a: 'must have gone', check: 'must の直後が原形の have になっていて、went のような過去形が入っていないことを確かめます。' }] },
      { h: '後悔・非難を表す形', t: '「本当はこうすべきだったのに」と、過去の行動を後悔したり、相手を責めたりする表現です。どれも「実際にはその反対だった」という意味がふくまれます。\n【should have + 過去分詞】〜すべきだったのに(実際はしなかった)。例:I should have studied harder.(もっと勉強しておくべきだった)\n【shouldn\'t have + 過去分詞】〜すべきではなかったのに(実際はした)。例:You shouldn\'t have told her the secret.(彼女に秘密を話すべきではなかったのに)\n【need not (needn\'t) have + 過去分詞】〜する必要はなかったのに(実際はした)。例:You needn\'t have brought an umbrella.(かさを持ってくる必要はなかったのに)\n【could have + 過去分詞】〜できたのに(実際はしなかった)。例:You could have asked me for help.(私に助けを求めることもできたのに)',
        key: 'should have done=すべきだったのに(しなかった)、needn\'t have done=する必要はなかったのに(した)。',
        ex: [{ q: '和訳しよう。\n(1) I should have taken a taxi.\n(2) You needn\'t have hurried.', hint: 'どちらも「実際にはどうだったか」を考えると、訳がはっきりします。', steps: ['(1) should have + 過去分詞=〜すべきだったのに。実際はタクシーに乗らなかった。', '(1) 「タクシーに乗るべきだった」と後悔の気持ちをこめて訳す。', '(2) needn\'t have + 過去分詞=〜する必要はなかったのに。実際は急いだ。', '(2) 「急ぐ必要はなかったのに」と訳す。'], a: '(1) タクシーに乗るべきだった(のに、乗らなかった)。(2) 急ぐ必要はなかったのに(あなたは急いでしまった)。', check: '(1) は「実際は乗らなかった」、(2) は「実際は急いだ」という事実が、それぞれの訳に合っているかを確かめます。' }] },
      { h: 'よく出る助動詞の慣用表現', t: '【had better + 原形】〜したほうがよい(しないと困ったことになる、という強い忠告)。否定は had better not 〜 です。例:You had better see a doctor.(医者にみてもらったほうがいい)\n【would rather A (than B)】(B するより)むしろ A したい。例:I would rather stay home than go out.(出かけるより家にいたい)\n【used to + 原形】以前はよく〜した/以前は〜だった(今はちがう)。例:There used to be a big tree here.(以前はここに大きな木があった)\n【may well + 原形】〜するのももっともだ/たぶん〜だろう。【may as well + 原形】〜したほうがよい(〜してもよい)。\nhad better は目上の人に使うと命令のように聞こえることがあるので、ていねいに言うときは should を使います。',
        ex: [{ q: '正しいほうを選ぼう。\n(1) You (had better not / had not better) eat too much.\n(2) There (used to / would) be a bookstore on this corner, but now it is a café.', hint: '(1) は not の位置、(2) は「動作」か「状態」かに注目します。', steps: ['(1) had better は2語で1つの助動詞のように使うので、not はその後ろに置く → had better not。', '(2) 「以前は本屋があった(今はない)」は過去の状態。', '(2) would は過去によくした「動作」にしか使えないので、状態には used to を使う。'], a: '(1) had better not(食べすぎないほうがいい)(2) used to(以前はこの角に本屋があったが、今はカフェになっている)', check: '(2) の but now it is a café が「今はちがう」ことを示していて、used to の意味と合っていることを確かめます。' }] },
      { h: 'SVOO・SVOC の受動態', t: '【SVOO】は O が2つあるので、受動態も2通り作れます。\n能動態 He gave me a book. → I was given a book by him.(私は彼から本をもらった)/A book was given to me by him.(物を主語にするときは、人の前に to を置く)\n【SVOC】は O を主語にし、C は be + 過去分詞の後ろにそのまま残します。C を主語にすることはできません。\n能動態 They named the baby Hana. → The baby was named Hana.(その赤ちゃんはハナと名づけられた)\nby 〜 は、だれがしたかが重要でないときや、一般の人(they・people)のときは省略します。',
        key: 'SVOO の受動態は人・物の2通り。SVOC の受動態は O を主語にし、C は後ろに残します。' },
      { h: '使役・助動詞をふくむ受動態', t: '【make O + 原形】(O に〜させる)の受動態では、原形が【to 不定詞】に変わります。\n能動態 The teacher made us wait. → We were made to wait by the teacher.(私たちは先生に待たされた)\n同じように、知覚動詞の see・hear も、受動態では to が必要です。例:He was seen to enter the room.(彼はその部屋に入るところを見られた)\n助動詞をふくむ受動態は【助動詞 + be + 過去分詞】です。例:The work must be done by tomorrow.(その仕事は明日までに終えなければならない)',
        key: 'make O 原形・see O 原形 の受動態では、原形が to 不定詞になります(be made to do)。',
        ex: [{ q: '受動態に書きかえよう。\n(1) They call the dog Max.\n(2) My mother made me clean my room.', hint: '(1) は SVOC、(2) は make O + 原形 の文です。', steps: ['(1) SVOC。O(the dog)を主語にし、C(Max)は called の後ろに残す。', '(1) 主語 The dog は3人称単数・現在なので is called。they は一般の人なので by them は省く。', '(2) make O + 原形 の受動態。O(me)を主語の I にし、原形 clean は to clean にする。', '(2) 過去の文なので was made。'], a: '(1) The dog is called Max.(その犬はマックスと呼ばれている)(2) I was made to clean my room by my mother.(私は母に部屋を掃除させられた)', check: '(2) で made の後ろに to が入っているかを確かめます(× I was made clean)。' }] }
    ],
    faq: [
      ['must not と don\'t have to は、どうちがうの?', 'must not は「〜してはいけない」(禁止)、don\'t have to は「〜しなくてもよい」(不必要)です。You must not run here.(ここで走ってはいけない)/You don\'t have to run.(走らなくてもいい)\n推量の「〜のはずがない」は、どちらでもなく can\'t を使います。'],
      ['should have done は「〜したはずだ」の意味にもなるの?', 'なります。should には「当然〜のはずだ」という推量の意味もあるので、He should have arrived by now.(彼はもう着いているはずだ)のようにも使います。\nどちらの意味かは文脈で判断しますが、入試では「すべきだったのに(しなかった)」の後悔の意味がよくねらわれます。'],
      ['used to と would は、どちらも「よく〜した」なの?', 'どちらも過去の習慣を表せますが、would は動作(よく〜したものだ)にしか使えません。\nThere used to be a tree here. のような「以前は〜だった」という状態には used to だけを使います。']
    ],
    terms: [['推量', '話し手が「たぶん〜だろう」と判断すること'], ['must have + 過去分詞', '〜したにちがいない'], ['can\'t have + 過去分詞', '〜したはずがない'], ['should have + 過去分詞', '〜すべきだったのに(しなかった)'], ['need not have + 過去分詞', '〜する必要はなかったのに(した)'], ['had better', '〜したほうがよい(強い忠告)。否定は had better not']],
    miss: ['「〜のはずがない」を must not で表してしまう。must not は禁止なので、推量の否定は can\'t と覚えます。', '過去の推量で、He must went. のように助動詞の後ろを過去形にしてしまう。助動詞の後ろは原形なので、must have gone とします。', 'should have done を「〜したはずだ」とだけ覚えて、「すべきだったのに」の後悔の意味を落とす。実際はどうだったかを考えて訳します。', 'make O 原形 の受動態で、to を入れ忘れる(× We were made wait.)。受動態では原形が to 不定詞になると覚えます。'],
    sum: ['確信の強さは must > should > may・might。否定の推量は can\'t。', '過去への推量は 助動詞 + have + 過去分詞。', 'should have done=すべきだったのに、needn\'t have done=する必要はなかったのに。', 'SVOO の受動態は2通り、SVOC は C を後ろに残す。', 'be made to do のように、使役・知覚の原形は受動態で to 不定詞になる。'],
    next: '次は「不定詞・動名詞・分詞の基本」です。助動詞の後ろは原形でしたが、動詞を名詞や形容詞のように使う形を学ぶと、表現の幅が大きく広がります。'
  };

  // ===== 準動詞の基本 =====
  L.e_inf = {
    goal: '不定詞の3用法・動名詞・分詞の基本が分かり、動詞によって to 不定詞と動名詞を正しく使い分けられるようになる。',
    intro: '「to + 動詞の原形」(不定詞)、「動詞の ing 形」(動名詞・現在分詞)、「過去分詞」は、動詞からできているのに、文の中では名詞・形容詞・副詞のはたらきをします。まとめて【準動詞】といいます。どれを使うかは意味とイメージで決まります。大まかに言えば、to 不定詞は【これから先のこと】、動名詞は【すでにしていること・実際にしていること】です。',
    pre: '中学では【to + 動詞の原形】(不定詞)を習いました。I want to go.(行きたい)、I went to the park to play tennis.(テニスをするために公園へ行った)のような形です。\n【動名詞】は動詞の ing 形で、「〜すること」の意味です。例:I like playing the guitar.(私はギターをひくことが好きだ)\n現在進行形 I am playing … の playing は「〜している」の意味で、これは【現在分詞】です。動名詞と同じ ing 形ですが、はたらきがちがいます。\n品詞のはたらきもおさらいします。名詞は S・O・C になり、形容詞は名詞を説明し、副詞は動詞・形容詞・文全体などを説明します。準動詞は、この3つのどれかのはたらきをします。',
    secs: [
      { h: '不定詞の3用法', t: '不定詞(to + 原形)は、文の中でのはたらきによって3つの用法に分かれます。\n【名詞的用法】「〜すること」。S・O・C になります。例:To learn a language takes time.(言語を学ぶことは時間がかかる)→ S/I want to be a doctor.(医者になりたい)→ want の O\n【形容詞的用法】「〜するための・〜すべき」。前の名詞を説明します。例:I have a lot of homework to do.(やるべき宿題がたくさんある)/I need something to drink.(何か飲み物がほしい)\n【副詞的用法】動詞や形容詞を説明します。「〜するために」(目的)、「〜して」(感情の原因)など。例:I went to the library to study.(勉強するために図書館へ行った)/I\'m glad to see you.(あなたに会えてうれしい)\n見分けるときは、「to 〜」が文の中で何のはたらきをしているかを考えます。S・O・C なら名詞的、直前の名詞を説明していれば形容詞的、それ以外は副詞的です。',
        key: '不定詞は、S・O・C になれば名詞的、前の名詞を説明すれば形容詞的、目的・原因などを表せば副詞的用法です。',
        ex: [{ q: '下線部の不定詞の用法を答え、和訳しよう。\n(1) My dream is to travel around the world.\n(2) She has no friends to help her.\n(3) He got up early to catch the first train.', hint: 'to 〜 が、S・O・C か、前の名詞の説明か、それ以外かを見ます。', steps: ['(1) to travel 〜 は is の後ろで、My dream=to travel 〜 の関係 → C になる名詞的用法。', '(2) to help her は直前の名詞 friends を説明している → 形容詞的用法。', '(3) to catch the first train は got up early の目的(〜するために)を表す → 副詞的用法。'], a: '(1) 名詞的用法:私の夢は世界中を旅することだ。(2) 形容詞的用法:彼女には助けてくれる友達がいない。(3) 副詞的用法:彼は始発電車に乗るために早く起きた。', check: '(3) は in order to catch に置きかえても意味が変わらないので、目的の副詞的用法だと確かめられます。' }] },
      { h: 'to 不定詞をとる動詞・動名詞をとる動詞', t: '動詞によって、後ろ(目的語)に to 不定詞をとるか、動名詞をとるかが決まっています。\n【to 不定詞をとる動詞】これから先のことを表すものが多くあります。\nwant(〜したい)、hope・wish(〜を望む)、decide(〜しようと決める)、plan(〜するつもりだ)、promise(〜すると約束する)、expect(〜するつもりだ)、refuse(〜するのを断る)、manage(なんとか〜する)。例:I decided to study abroad.(留学しようと決めた)\n【動名詞をとる動詞】すでにしていること・実際にしていることを表すものが多くあります。\nenjoy(〜を楽しむ)、finish(〜し終える)、avoid(〜を避ける)、mind(〜をいやがる)、give up(〜をやめる)、practice(〜を練習する)、consider(〜しようかと考える)、deny(〜したことを否定する)、suggest(〜しようと提案する)。\n例:I enjoyed talking with her.(彼女との会話を楽しんだ)× I enjoyed to talk with her. とは言いません。',
        key: 'want・decide・hope など「これから」の動詞は to 不定詞、enjoy・finish・avoid など「実際にしている」動詞は動名詞をとります。',
        ex: [{ q: '( ) 内の動詞を正しい形にしよう。\n(1) We decided ( leave ) early.\n(2) Would you mind ( open ) the window?\n(3) He finally finished ( write ) the report.', hint: '動詞が「これから」を表すか、「実際にしていること」を表すかを考えます。', steps: ['(1) decide は「これからしようと決める」→ to 不定詞をとる → to leave。', '(2) mind(〜をいやがる)は動名詞をとる動詞 → opening。', '(3) finish(〜し終える)は、実際にしていることを終えるので動名詞 → writing。'], a: '(1) to leave(私たちは早く出発することに決めた)(2) opening(窓を開けていただけませんか)(3) writing(彼はついに報告書を書き終えた)', check: '(3) は「書いている最中のことを終える」と考えると、すでにしていること=動名詞のイメージに合います。' }] },
      { h: 'to と ing で意味が変わる動詞', t: 'どちらもとれるけれど、意味が変わる動詞があります。「to=これから」「ing=すでに・実際に」のイメージで考えます。\n【remember to do】(これから)忘れずに〜する/【remember doing】(過去に)〜したことを覚えている。例:Remember to lock the door.(忘れずにドアのかぎをかけてね)/I remember locking the door.(ドアにかぎをかけたのを覚えている)\n【forget to do】〜し忘れる/【forget doing】〜したことを忘れる\n【try to do】〜しようとする/【try doing】ためしに〜してみる\n【regret to do】残念ながら〜する/【regret doing】〜したことを後悔する\n【stop doing】〜するのをやめる。例:He stopped smoking.(彼はたばこを吸うのをやめた)\nなお He stopped to smoke. は「たばこを吸うために立ち止まった」の意味です。この to smoke は stop の目的語ではなく、目的を表す副詞的用法です。',
        key: 'remember・forget・try・regret は、to=これから、ing=すでにしたこと、で意味が変わります。',
        ex: [{ q: '( ) 内の正しいほうを選び、和訳しよう。\n(1) Don\'t forget (to call / calling) me tonight.\n(2) I\'ll never forget (to visit / visiting) Kyoto with you last year.', hint: 'tonight と last year が、これからのことか、すでにしたことかの手がかりです。', steps: ['(1) tonight(今夜)=これから先のこと → to 不定詞。forget to do=〜し忘れる。', '(1) Don\'t forget to call=忘れずに電話してね。', '(2) last year(去年)=すでにしたこと → 動名詞。forget doing=〜したことを忘れる。'], a: '(1) to call(今夜、忘れずに私に電話してね)(2) visiting(去年あなたと京都を訪れたことは、決して忘れないでしょう)', check: '(1) は電話するのが「これから」、(2) は訪れたのが「すでに」であることが、時を表す語と合っているかを確かめます。' }] },
      { h: '分詞の基本:名詞を説明する', t: '分詞には【現在分詞(〜ing)】と【過去分詞】があり、どちらも形容詞のように名詞を説明できます。\n現在分詞は「〜している」(能動)で、a sleeping baby(眠っている赤ちゃん)。過去分詞は「〜された」(受動)で、a broken window(割られた窓)です。\n分詞1語なら名詞の前、ほかの語句をともなうなら名詞の後ろに置きます。例:The boy playing tennis is my brother.(テニスをしている少年は私の弟だ)/This is a car made in Japan.(これは日本で作られた車だ)\n能動か受動かは、【説明される名詞との関係】で決めます。窓は自分で割るのではなく「割られる」ので broken です。\n感情を表す分詞も同じ考え方です。The game was exciting.(試合はわくわくさせるものだった)/I was excited.(私はわくわくさせられた=わくわくした)',
        key: '分詞は、説明される名詞が「する」側なら〜ing、「される」側なら過去分詞にします。',
        ex: [{ q: '( ) 内の動詞を正しい形にしよう。\n(1) Look at the ( fall ) leaves.(落ちている葉)\n(2) English is a language ( speak ) all over the world.', hint: '説明される名詞(leaves・a language)が「する」側か「される」側かを考えます。', steps: ['(1) 葉は自分で「落ちる」→ 能動 → 現在分詞 falling。1語なので名詞の前に置く。', '(2) 言語は人に「話される」→ 受動 → 過去分詞 spoken。', '(2) all over the world をともなうので、名詞 a language の後ろに置く。'], a: '(1) falling(落ちている葉を見て)(2) spoken(英語は世界中で話されている言語だ)', check: '「葉が落ちる」「言語が話される」と、名詞を主語にした文に直して意味が通るかを確かめます。' }] },
      { h: '意味上の主語と否定の形', t: '不定詞・動名詞の動作を「だれがするのか」を示したいときがあります。これを【意味上の主語】といいます。\n不定詞では【for + 人 + to 〜】で表します。例:It is easy for me to answer this question.(この質問に答えるのは、私にはやさしい)→ 答えるのは me です。\nただし、kind・nice・careless など【人の性質】を表す形容詞のときは【of + 人】を使います。例:It is kind of you to help me.(手伝ってくれるなんて、あなたは親切ですね)→ You are kind. が成り立つからです。\n動名詞では、所有格か目的格を ing の前に置きます。例:Do you mind my (me) opening the window?(私が窓を開けてもかまいませんか)\n否定は、不定詞・動名詞の【直前】に not を置きます。例:I decided not to go.(行かないことに決めた)/I\'m sorry for not calling you.(電話しなくてごめんなさい)',
        key: '意味上の主語はふつう for + 人。人の性質を表す形容詞(kind・careless など)なら of + 人。',
        ex: [{ q: '( ) に for か of を入れよう。\n(1) It is necessary ( ) you to sleep well.\n(2) It was careless ( ) him to leave the door open.', hint: '「人 is 形容詞」の文が成り立つかを考えます。', steps: ['(1) 「You are necessary(あなたは必要だ)」は、ここでは意味が通らない。necessary は人の性質ではない。', '(1) よって for を使う。', '(2) 「He was careless(彼は不注意だった)」は成り立つ。careless は人の性質を表す。', '(2) よって of を使う。'], a: '(1) for(あなたはよく眠ることが必要だ)(2) of(ドアを開けっぱなしにしておくなんて、彼は不注意だった)', check: '(2) は He was careless to leave the door open. と書きかえても意味が通ることで、of が正しいと確かめられます。' }] }
    ],
    faq: [
      ['不定詞と動名詞は、どちらも「〜すること」なのに、何がちがうの?', '意味はどちらも「〜すること」になりますが、to 不定詞は「これから先に向かう」、動名詞は「すでにしている・実際にしている」というイメージのちがいがあります。\nそのため、want(これからしたい)は to 不定詞、enjoy(実際にしていることを楽しむ)は動名詞をとります。'],
      ['動名詞と現在分詞は、どう見分けるの?', '形は同じ ing ですが、はたらきがちがいます。「〜すること」と訳せて S・O・C や前置詞の後ろに来るなら動名詞、「〜している」と訳せて名詞を説明したり進行形を作ったりするなら現在分詞です。\nI like playing chess.(チェスをすることが好きだ)は動名詞、He is playing chess.(チェスをしている)は現在分詞です。'],
      ['like や begin の後ろは、どちらでもいいの?', 'like・love・begin・start などは、to 不定詞も動名詞もとれて、意味もほとんど変わりません。I like to swim. も I like swimming. も「泳ぐのが好きだ」です。\n意味が変わるのは、remember・forget・try・regret・stop などです。']
    ],
    terms: [['準動詞', '不定詞・動名詞・分詞のこと。動詞からできて、名詞・形容詞・副詞のはたらきをする'], ['不定詞', 'to + 動詞の原形'], ['動名詞', '動詞の ing 形で「〜すること」の意味。名詞のはたらき'], ['現在分詞', '動詞の ing 形で「〜している」の意味。形容詞のはたらき'], ['過去分詞', '「〜された」の意味。受動態・完了形にも使う'], ['意味上の主語', '不定詞・動名詞の動作をする人。for 〜・of 〜・所有格などで示す']],
    miss: ['enjoy to do、finish to do のように、動名詞をとる動詞に to 不定詞を続けてしまう。動詞ごとに「to か ing か」をセットで覚えます。', 'remember to do と remember doing の意味を逆に覚える。「to=これから」のイメージで確かめます。', 'stop to do を「〜するのをやめる」と訳してしまう。正しくは「〜するために立ち止まる」です。', '分詞の能動・受動を、日本語の感覚だけで決めてしまう。説明される名詞を主語にした文を作って決めます。'],
    sum: ['不定詞は 名詞的・形容詞的・副詞的 の3用法。', 'to 不定詞=これから先、動名詞=すでに・実際に、のイメージ。', 'want・decide・hope は to、enjoy・finish・avoid は ing。', 'remember・forget・try・regret は to と ing で意味が変わる。', '分詞は 〜ing=能動、過去分詞=受動。名詞との関係で決める。', '意味上の主語は for + 人、人の性質なら of + 人。'],
    next: '次は「分詞・分詞構文」です。この単元で学んだ「〜ing=能動、過去分詞=受動」の考え方が、そのまま分詞構文を作るときの決め手になります。'
  };

  // ===== 関係詞 =====
  L.e_h4 = {
    goal: '関係副詞(where・when・why・how)と関係代名詞 what を正しく使い分け、非制限用法・複合関係詞の意味もとれるようになる。',
    intro: '関係代名詞(who・which・that)は、名詞を後ろから説明する節を作りました。【関係副詞】も同じように名詞を説明しますが、使うのは「場所・時・理由」などを表す名詞のときです。どちらを使うかは、後ろの文が【完全か、欠けているか】で決まります。この判定ができれば、関係詞の問題はほとんど解けます。',
    pre: '中学で習った【関係代名詞】(who・which・that)は、名詞を後ろから説明する節を作る語です。例:I have a friend who lives in Kyoto.(私には京都に住んでいる友達がいる)\nこのとき、説明される名詞(a friend)を【先行詞】といいます。先行詞が人なら who、物なら which、どちらでも that が使えました。\n関係代名詞は、後ろの節の中で主語(主格)や目的語(目的格)の役割をします。who lives の who は lives の主語、This is the book (which) I bought. の which は bought の目的語です。目的格は省略できます。\nこの単元の決め手は、「文が完全か不完全か」という見方です。完全な文とは、S・V と、その動詞が必要とする O・C がすべてそろった文のことです。',
    secs: [
      { h: '関係副詞 where・when・why・how', t: '関係副詞も、関係代名詞と同じく、先行詞を後ろから説明する節を作ります。使い分けは先行詞の種類で決まります。\n【where】場所:This is the house where I was born.(これは私が生まれた家だ)\n【when】時:I remember the day when we first met.(私たちが初めて会った日を覚えている)\n【why】理由(先行詞は the reason):That is the reason why I was late.(それが私が遅れた理由だ)\n【how】方法:This is how he solved the problem.(このようにして彼はその問題を解いた)\nhow は先行詞 the way と一緒には使いません。the way か how の【どちらか一方】だけを使います。\n○ This is the way he solved the problem. ○ This is how he solved the problem. × This is the way how he solved the problem.',
        key: '場所 where、時 when、理由 why、方法 how。how は the way と一緒に使いません。',
        ex: [{ q: '( ) に適切な関係副詞を入れよう。\n(1) Do you remember the day ( ) we first met?\n(2) Tell me the reason ( ) you were absent.\n(3) This is the park ( ) I often play.', hint: '先行詞が「時・理由・場所」のどれかを見ます。', steps: ['(1) 先行詞 the day は時。後ろの we first met は完全な文 → when。', '(2) 先行詞 the reason は理由。後ろの you were absent は完全な文 → why。', '(3) 先行詞 the park は場所。後ろの I often play は、play が「遊ぶ」という自動詞なので完全な文 → where。'], a: '(1) when(私たちが初めて会った日を覚えていますか)(2) why(あなたが欠席した理由を教えてください)(3) where(ここは私がよく遊ぶ公園だ)', check: '(3) は where を in which に置きかえて the park in which I often play としても意味が通ることを確かめます。' }] },
      { h: '関係副詞か関係代名詞か(最重要の判定法)', t: '先行詞が場所だからといって、いつも where になるわけではありません。決め手は【関係詞の後ろの文】です。\n後ろが【完全な文】(S・V・O などが全部そろっている)なら関係副詞、【不完全な文】(S や O が欠けている)なら関係代名詞です。\n例:This is the town where I lived ten years ago. → I lived ten years ago は、live が自動詞なのでこれで完全 → where\n例:This is the town which I visited ten years ago. → I visited ten years ago は、visit(〜を訪れる)の O が欠けている → which\nなぜこうなるのでしょうか。関係代名詞は、後ろの節の中で S や O の「代わり」をする語なので、その分だけ後ろの文が欠けます。関係副詞は副詞(M)の代わりなので、後ろの文は欠けないのです。\n関係副詞は「前置詞 + which」に言いかえられます。例:the house where I was born = the house in which I was born',
        key: '関係詞の後ろが完全な文なら関係副詞、S や O が欠けた不完全な文なら関係代名詞です。',
        ex: [{ q: '( ) に where か which を入れよう。\n(1) Kyoto is a city ( ) many people visit every year.\n(2) Kyoto is a city ( ) you can see many old temples.', hint: '先行詞ではなく、( ) の後ろの文が完全かどうかで決めます。', steps: ['(1) 後ろ:many people visit every year。visit は他動詞なのに O がない → 不完全 → 関係代名詞。', '(1) 先行詞 a city は物なので which。', '(2) 後ろ:you can see many old temples。S・V・O がそろっている → 完全 → 関係副詞。', '(2) 先行詞は場所なので where。'], a: '(1) which(京都は毎年多くの人が訪れる都市だ)(2) where(京都は古い寺をたくさん見られる都市だ)', check: '(1) の which を元の位置に戻すと many people visit the city(=Kyoto)となり、O が補われることを確かめます。' }] },
      { h: '先行詞をふくむ what', t: '【what】は「〜すること・〜するもの」という意味で、先行詞をふくんだ関係代名詞です。what = the thing(s) which と考えます。だから what の前に先行詞はつけません。\n例:What he said was true.(彼が言ったことは本当だった)→ What he said が S。例:This is what I wanted.(これが私のほしかったものだ)→ what I wanted が C。\nwhat の後ろも、関係代名詞なので【不完全な文】になります(said・wanted の O が欠けている)。\n慣用表現:what is called(いわゆる)、what S is(今の S の姿)、what is more(さらに)。例:My parents made me what I am.(両親のおかげで今の私がある)',
        key: 'what=the thing(s) which。前に先行詞を置かず、後ろは不完全な文になります。',
        ex: [{ q: '和訳しよう。\n(1) What surprised me was his answer.\n(2) Don\'t put off till tomorrow what you can do today.', hint: 'what のかたまりがどこまでで、文の中で何になっているかを見ます。', steps: ['(1) What surprised me(私を驚かせたこと)が S、was が V、his answer が C。', '(1) what の後ろは surprised の主語が欠けた不完全な文になっている。', '(2) put off(延期する)の O は what you can do today(今日できること)。till tomorrow が間にはさまっている。', '(2) Don\'t で始まる命令文なので「〜するな」と訳す。'], a: '(1) 私を驚かせたのは、彼の答えだった。(2) 今日できることを明日まで延ばすな。', check: '(1) の What を The thing which に置きかえても意味が変わらないことを確かめます。' }] },
      { h: '非制限用法(コンマのある関係詞)', t: '関係詞の前に【コンマ】をつけると、先行詞についての情報を「ちなみに〜」と付け足す言い方になります。これを【非制限用法】といいます。\n例:I have a brother, who lives in Osaka.(私には兄が1人いて、その兄は大阪に住んでいる)/I have a brother who lives in Osaka.(私には大阪に住んでいる兄がいる)→ ほかにも兄弟がいるかもしれない\n非制限用法では【that は使えません】。\nwhich は、前の文の内容全体を先行詞にすることができます。例:He said he was sick, which was not true.(彼は病気だと言ったが、それは本当ではなかった)\nwhere・when も非制限用法で使えます。例:I went to Nara, where I saw many deer.(奈良へ行き、そこでたくさんのシカを見た)',
        key: 'コンマ + 関係詞は「ちなみに〜」の付け足し。that は使えず、which は前の文全体も受けられます。',
        ex: [{ q: '2つの文の意味のちがいを説明しよう。\n(1) He has two sons who are doctors.\n(2) He has two sons, who are doctors.', hint: 'コンマがあるかないかで、息子が何人いるかの情報が変わります。', steps: ['(1) コンマなし(制限用法)。who are doctors が two sons を限定している → 「医者である息子が2人」。', '(1) 医者ではない息子が、ほかにいる可能性がある。', '(2) コンマあり(非制限用法)。「息子が2人いる」と言い切ってから「ちなみに2人とも医者だ」と付け足している。', '(2) 息子は2人だけだと分かる。'], a: '(1) 彼には医者をしている息子が2人いる(ほかにも息子がいるかもしれない)。(2) 彼には息子が2人いて、2人とも医者だ。', check: '(2) は He has two sons, and they are doctors. と書きかえられることで、非制限用法だと確かめられます。' }] },
      { h: '複合関係詞(〜ever)', t: '関係詞に ever をつけた形を【複合関係詞】といいます。大きく2つの意味があります。\n【名詞のはたらき】whoever=〜する人はだれでも、whatever=〜するものは何でも。例:Whoever comes will be welcome.(来る人はだれでも歓迎される)/You can take whatever you like.(好きなものは何でも持っていっていいよ)\n【譲歩の副詞節】「たとえ〜でも」の意味で、no matter + 疑問詞 と同じです。例:Whatever happens, I will support you.(たとえ何が起きても、あなたを支える)= No matter what happens, …\n例:Wherever you go, I will follow you.(どこへ行こうとも、ついていく)\n【however + 形容詞・副詞 + S + V】は「どんなに〜しても」です。例:However hard you try, you can\'t finish it in a day.(どんなに一生けんめいやっても、1日では終えられない)\nhowever の直後に形容詞・副詞を置く語順に注意します(× However you try hard)。',
        key: 'however + 形容詞・副詞 + S + V=どんなに〜しても。形容詞・副詞は however の直後に置きます。',
        ex: [{ q: '和訳しよう。\nHowever busy she is, she reads the newspaper every morning.', hint: 'However の直後に形容詞 busy があることに注目します。', steps: ['However + 形容詞(busy)+ S + V → 「どんなに〜でも」という譲歩。', 'However busy she is=彼女がどんなに忙しくても。', '主節:she reads the newspaper every morning=毎朝新聞を読む。'], a: '彼女はどんなに忙しくても、毎朝新聞を読む。', check: 'No matter how busy she is, … と書きかえても同じ意味になることを確かめます。' }] }
    ],
    faq: [
      ['where と in which は、いつでも言いかえられるの?', '先行詞が場所で、後ろが完全な文なら、多くの場合 in which(at which など)に言いかえられます。前置詞は先行詞に合わせて選びます(the house in which、the station at which)。\nただし、関係副詞 where の前に前置詞をつけることはできません(× in where)。'],
      ['that は関係副詞の代わりにも使えるの?', 'the day that 〜 や the reason that 〜 のように、that が when・why の代わりに使われることがあります。また、when・why は省略されることも多く、the day we met のようにも言います。\nただし、非制限用法(コンマの後)では that は使えません。'],
      ['what と which は、どうちがうの?', 'which は前に先行詞が必要ですが、what は先行詞をふくんでいる(=the thing which)ので、前に名詞を置きません。\nthe book which I bought(私が買った本)/what I bought(私が買ったもの)のように使い分けます。']
    ],
    terms: [['先行詞', '関係詞の節によって説明される名詞'], ['関係副詞', 'where・when・why・how。後ろに完全な文がくる'], ['関係代名詞 what', '「〜すること・もの」。先行詞をふくむ'], ['非制限用法', 'コンマ + 関係詞。先行詞に情報を付け足す。that は使えない'], ['複合関係詞', 'whoever・whatever・however など。「〜は何でも」や「たとえ〜でも」の意味'], ['完全な文', 'S・V と、動詞に必要な O・C がすべてそろった文']],
    miss: ['先行詞が場所というだけで where を選んでしまう。後ろの文が不完全なら which なので、必ず後ろを確かめます。', 'the way how と、the way と how を一緒に使ってしまう。どちらか一方だけにします。', 'what の前に先行詞を置いて、the thing what としてしまう。what は先行詞をふくむと覚えます。', '非制限用法(コンマの後)に that を使ってしまう。コンマの後は who・which にします。'],
    sum: ['場所 where、時 when、理由 why、方法 how(the way とは併用しない)。', '後ろが完全な文なら関係副詞、不完全なら関係代名詞。', 'what=the thing(s) which。前に先行詞を置かない。', 'コンマ + 関係詞は付け足しの情報。that は不可、which は前の文全体も受ける。', 'however + 形容詞・副詞 + S + V=どんなに〜しても。'],
    next: '次は「比較」です。関係詞と同じく、比較も「何と何を比べているか」という文の構造を見る力が大切なので、続けて学ぶと構造をとる力がさらにのびます。'
  };

  // ===== 分詞構文 =====
  L.e_h3 = {
    goal: '分詞構文を作ったり訳したりでき、能動(〜ing)と受動(過去分詞)を主語との関係で正しく選べるようになる。',
    intro: '「駅まで歩いていたとき、私はケンに会った」は、When I was walking to the station, I met Ken. です。これを、Walking to the station, I met Ken. と短くした形が【分詞構文】です。接続詞と主語を省いて、分詞で文をつなぐので、文がひきしまります。英文を読むときは、省かれた接続詞を自分で補って意味を考えます。',
    pre: '【現在分詞(〜ing)】は「〜している」、【過去分詞】は「〜された」という意味で、どちらも形容詞のように名詞を説明できます。a sleeping baby(眠っている赤ちゃん)、a broken window(割られた窓)。\n【接続詞】は、文と文をつなぐ語です。when(〜とき)、because(〜なので)、while(〜する間に)、if(もし〜なら)、though(〜だけれども)などがあります。\n接続詞でつないだ文には、主節と、接続詞で始まる従属節(副詞節)があります。When I was walking to the station, I met Ken. では、I met Ken が主節です。\n【完了形】(have + 過去分詞)は、「それより前」を表すことができました。この3つの知識を組み合わせたのが分詞構文です。',
    secs: [
      { h: '分詞構文の作り方', t: '接続詞のある文から、次の手順で分詞構文を作ります。\n① 接続詞を消す。② 主節と主語が同じなら、主語を消す。③ 動詞を【〜ing(現在分詞)】にする。\n例:When I was walking to the station, I met Ken. → When と I を消し、was walking を Walking にする(be動詞は being になり、省かれる)→ Walking to the station, I met Ken.\n例:Because she felt tired, she went to bed early. → Feeling tired, she went to bed early.(疲れていたので、彼女は早く寝た)\nなぜ主語を消せるのでしょうか。分詞構文の主語は、主節の主語と同じだと読む人が分かるからです。主語がちがうときは消せません(独立分詞構文)。',
        key: '接続詞を消す → 主節と同じ主語を消す → 動詞を〜ing にする、が分詞構文の作り方です。',
        ex: [{ q: '分詞構文を使って書きかえよう。\n(1) While I was listening to music, I fell asleep.\n(2) Because he lives near the school, he walks to school.', hint: 'まず、接続詞の節と主節の主語が同じかどうかを確かめます。', steps: ['(1) 主語はどちらも I → 接続詞 While と主語 I を消す。', '(1) was listening → (Being) listening → Listening。', '(2) 主語はどちらも he → Because と he を消す。', '(2) lives → Living。'], a: '(1) Listening to music, I fell asleep.(音楽を聞いているうちに、私は眠ってしまった)(2) Living near the school, he walks to school.(学校の近くに住んでいるので、彼は歩いて通学している)', check: '書きかえた文の分詞の主語が、主節の主語(I・he)と一致しているかを確かめます。' }] },
      { h: '分詞構文の意味', t: '接続詞を消しているので、意味は文脈から判断します。主なものは次の5つです。\n【時】〜するとき・〜していると:Opening the door, I found a cat.(ドアを開けると、ねこがいた)\n【理由】〜なので:Having no money, I couldn\'t buy it.(お金がなかったので、それを買えなかった)\n【付帯状況】〜しながら:He watched TV, eating snacks.(彼はおやつを食べながらテレビを見た)\n【条件】〜すれば:Turning left, you will find the post office.(左に曲がれば、郵便局が見つかります)\n【譲歩】〜だけれども:Admitting what you say, I still disagree.(あなたの言うことは認めるが、やはり賛成できない)\n入試や読解では、時・理由・付帯状況が特によく出ます。迷ったら「〜して、」とゆるくつないで訳し、文脈に合う接続詞を考えます。',
        key: '分詞構文の意味は、時・理由・付帯状況・条件・譲歩。迷ったら「〜して、」とつないでから文脈で決めます。',
        ex: [{ q: '和訳しよう。\n(1) Seeing the police officer, the man ran away.\n(2) Having nothing to do, I went to bed early.', hint: '分詞の部分と主節の関係が、「時」か「理由」かを考えます。', steps: ['(1) Seeing the police officer=警官を見た。主節は「その男は逃げ出した」。', '(1) 「見たとき(見て)」と時の関係でつなぐのが自然。', '(2) Having nothing to do=何もすることがなかった。主節は「早く寝た」。', '(2) 「することがなかったので」と理由の関係でつなぐのが自然。'], a: '(1) 警官を見ると(見て)、その男は逃げ出した。(2) 何もすることがなかったので、私は早く寝た。', check: '(2) を Because I had nothing to do, I went to bed early. に戻しても意味が通ることを確かめます。' }] },
      { h: '受動・完了・否定の分詞構文', t: '【受動】主語が「〜される」側なら Being + 過去分詞。Being はふつう省略され、【過去分詞】で始まります。例:Seen from the hill, the town looks beautiful.(丘から見ると、その町は美しく見える)→ 町は「見られる」側\n【完了】主節よりも前のことなら【Having + 過去分詞】。例:Having finished my homework, I went out.(宿題を終えてから、外出した)\n【否定】not や never を分詞の【直前】に置きます。例:Not knowing what to say, I kept silent.(何と言えばよいか分からなかったので、黙っていた)\n能動か受動かは、【分詞構文の意味上の主語(ふつうは主節の主語)】との関係で決めます。',
        key: '主語が「される」側なら過去分詞、主節より前のことなら Having + 過去分詞、否定は Not を分詞の前に置きます。',
        ex: [{ q: '( ) 内の動詞を正しい形にしよう。\n( Write ) in easy English, this book is good for beginners.', hint: '主節の主語 this book が「書く」側か「書かれる」側かを考えます。', steps: ['主節の主語は this book。分詞構文の意味上の主語も this book。', '本は自分で書くのではなく「書かれる」側 → 受動。', '受動の分詞構文は (Being) + 過去分詞。write の過去分詞は written。'], a: 'Written(やさしい英語で書かれているので、この本は初心者に向いている)', check: 'Because this book is written in easy English, … と接続詞の文に戻して、受動態になることを確かめます。' },
          { q: '分詞構文を使って書きかえよう。\nAfter I had finished my work, I went home.', hint: '仕事を終えたのと家に帰ったのは、どちらが先かを考えます。', steps: ['接続詞 After を消す。主節の主語も I なので、I も消す。', '仕事を終えたのは、家に帰るより前のこと → 完了の分詞構文 Having + 過去分詞。', 'had finished → Having finished。'], a: 'Having finished my work, I went home.(仕事を終えて、私は家に帰った)', check: 'Having + 過去分詞が「主節(went home)より前」を表していることを、時間の順番で確かめます。' }] },
      { h: '独立分詞構文と慣用表現', t: '分詞構文の主語が、主節の主語と【ちがう】ときは、主語を消さずに分詞の前に残します。これを【独立分詞構文】といいます。\n例:It being fine, we went hiking.(晴れていたので、私たちはハイキングに行った)→ 主語 It と we がちがう\n例:The bus being late, we took a taxi.(バスが遅れていたので、私たちはタクシーに乗った)\n主語がばくぜんとした「人一般」のときは、主語を書かずに慣用表現として使います。\n【generally speaking】一般的に言えば/【frankly speaking】率直に言えば/【judging from 〜】〜から判断すると/【considering 〜】〜を考えると/【speaking of 〜】〜と言えば',
        key: '分詞の主語が主節の主語とちがうときは、主語を分詞の前に残します(独立分詞構文)。' },
      { h: '付帯状況の with と have O 過去分詞', t: '【with + O + 分詞】は「O を〜した状態で」という付帯状況を表します。O と分詞の関係で、〜ing か過去分詞かを決めます。\n例:He was sitting with his eyes closed.(彼は目を閉じて座っていた)→ 目は「閉じられる」側なので過去分詞\n例:She came in with her dog following her.(彼女は犬をうしろにつれて入ってきた)→ 犬が「ついてくる」側なので〜ing\n【have + O + 過去分詞】は「O を〜してもらう・〜される」の意味です。\n例:I had my bike repaired.(自転車を修理してもらった)→ 自転車は「修理される」側/I had my wallet stolen.(財布を盗まれた)',
        key: 'with + O + 分詞、have + O + 過去分詞は、O が「する」側か「される」側かで形を決めます。',
        ex: [{ q: '( ) 内の動詞を正しい形にしよう。\nHe listened to me with his arms ( fold ).', hint: 'O(his arms)が「組む」側か「組まれる」側かを考えます。', steps: ['with + O + 分詞の付帯状況。O は his arms(彼のうで)。', 'うでは自分で組むのではなく、彼によって「組まれる」側 → 受動。', 'よって過去分詞 folded。'], a: 'folded(彼はうでを組んで私の話を聞いた)', check: '「His arms were folded.(うでが組まれていた)」と O を主語にした文が成り立つことを確かめます。' }] }
    ],
    faq: [
      ['分詞構文は、会話でも使うの?', '分詞構文は、主に書き言葉(小説・新聞・論説文)で使われます。会話では、When I was …、Because I … のように接続詞を使うのがふつうです。\nそのため入試では、作るよりも「読んで意味をとる」力がよく問われます。'],
      ['意味が「時」か「理由」か分からないときはどうするの?', 'まず「〜して、」とゆるくつないで訳してみます。そのうえで、前後の内容から「〜なので」と言える関係なら理由、「〜するとき」なら時、と決めます。\n実際の英文でも、どちらとも取れる場合は少なくありません。文全体の意味が通ることを優先しましょう。'],
      ['Being は、いつ省略できるの?', 'Being + 過去分詞(受動)や、Being + 形容詞・名詞の Being は、ふつう省略されます。(Being) tired, she went to bed early. のようにです。\nただし、It being fine のような独立分詞構文では、being を残すのがふつうです。']
    ],
    terms: [['分詞構文', '接続詞と主語を省き、分詞で始めて文をつなぐ形'], ['意味上の主語', '分詞の動作をする(される)人・もの。ふつうは主節の主語'], ['付帯状況', '「〜しながら」「〜した状態で」の意味'], ['独立分詞構文', '分詞の前に、主節とちがう主語を残した分詞構文'], ['完了分詞構文', 'Having + 過去分詞。主節より前のことを表す']],
    miss: ['Seen from the hill を Seeing にしてしまう。主語の町は「見られる」側なので、主節の主語との関係で決めます。', '主節より前のことなのに、Having + 過去分詞にせず、ただの〜ing にしてしまう。出来事の順番を確かめます。', 'not の位置をまちがえて、Knowing not … としてしまう。not は分詞の直前に置きます。', '主語がちがうのに主語を消してしまい、意味が通らない文になる。主語がちがうときは独立分詞構文にします。'],
    sum: ['接続詞を消す → 同じ主語を消す → 動詞を〜ing に。', '意味は 時・理由・付帯状況・条件・譲歩。文脈で決める。', '受動は過去分詞、主節より前は Having + 過去分詞、否定は Not を前に。', '主語がちがうときは、主語を残す(独立分詞構文)。', 'with + O + 分詞、have + O + 過去分詞 も「O との関係」で形を決める。'],
    next: '次は「仮定法」です。分詞構文で「時制のずれ(Having + 過去分詞)」に慣れておくと、時制を1つ過去にずらす仮定法の考え方もつかみやすくなります。'
  };

  // ===== 比較 =====
  L.e_comp = {
    goal: '倍数表現・the 比較級, the 比較級・no more than などの比較の慣用表現を、もとの比較の意味から理解して使えるようになる。',
    intro: '比較の基本は、as 〜 as(同じくらい)、比較級 + than(〜より)、the + 最上級(いちばん)の3つです。高校では、これに「〜の3倍」「〜すればするほど」「たった〜」などの表現が加わります。丸暗記すると混乱しがちですが、【もとの比較の意味】から考えると、理由ごと理解できます。',
    pre: '【原級】は形容詞・副詞のもとの形(tall、fast)、【比較級】は2つを比べる形(taller、faster)、【最上級】は3つ以上の中でいちばんを表す形(tallest、fastest)です。\n比較級・最上級は、短い語なら -er・-est をつけ、長い語(interesting、beautiful など)なら more・most を前に置きます。good・well は better - best、bad は worse - worst、many・much は more - most と不規則に変化します。\n中学で習った基本の形は、【as + 原級 + as】(同じくらい〜)、【比較級 + than】(〜より…)、【the + 最上級 + of・in】(いちばん〜)の3つでした。\n例:Ken is as tall as Tom.(ケンはトムと同じくらいの背の高さだ)/Ken is taller than Tom.(ケンはトムより背が高い)/Ken is the tallest in his class.(ケンはクラスでいちばん背が高い)',
    secs: [
      { h: '倍数表現', t: '「A は B の X 倍〜だ」は、【X times as 〜 as B】で表します。as 〜 as(同じくらい)に「X 倍」をかけるイメージです。\n例:This room is three times as large as that one.(この部屋はあの部屋の3倍の広さだ)\n2倍は【twice】、半分は【half】を使います。例:My brother has twice as many books as I do.(兄は私の2倍の本を持っている)/This box is half as heavy as that one.(この箱はあの箱の半分の重さだ)\n数えられる名詞の数を比べるときは、as many + 名詞 + as のように、名詞も as と as の間に入れます。\n名詞を使って【X times the 名詞 of B】と書くこともできます。例:This room is three times the size of that one.(この部屋はあの部屋の3倍の広さだ)\n3倍以上なら、X times + 比較級 + than も使えます。例:three times larger than',
        key: '倍数は「X times as 〜 as」。2倍は twice、半分は half を as の前に置きます。',
        ex: [{ q: '日本語に合うように ( ) に適語を入れよう。\n(1) この湖はあの湖の2倍の深さだ。This lake is ( ) as ( ) as that one.\n(2) 私は彼の3倍の本を持っている。I have three times as ( ) books as he does.', hint: '倍数を as の前に置き、as と as の間に原級を入れます。', steps: ['(1) 2倍は twice。「深い」は deep で、as と as の間は原級のまま。', '(1) This lake is twice as deep as that one.', '(2) books は数えられる名詞なので、数の多さを表す many を使う。', '(2) as many books as と、名詞も as と as の間に入れる。'], a: '(1) twice / deep (2) many', check: '倍数を外すと as deep as(同じ深さ)、as many books as(同じ数の本)になり、そこに「2倍・3倍」をかけた意味になっているか確かめます。' }] },
      { h: 'the 比較級, the 比較級 と比較級の強調', t: '【the 比較級 + S + V, the 比較級 + S + V】で、「〜すればするほど、ますます…」の意味です。2つの変化が比例していることを表します。\n例:The more you practice, the better you become.(練習すればするほど、上手になる)/The older he grew, the wiser he became.(彼は年をとるにつれて、賢くなった)\n比較級を強めて「ずっと〜」と言うときは、【much・far・even・still・a lot】を比較級の前に置きます。very は使いません。\n例:This book is much more interesting than that one.(この本はあの本よりずっとおもしろい)× very more interesting\nvery は「とても」と程度を強める語で、比較級が表す「差の大きさ」は表せないからです。',
        key: 'the 比較級, the 比較級=〜すればするほど…。比較級の強調は much・far・even(very は不可)。',
        ex: [{ q: '( ) 内の語を正しい形にしよう。また、(3) は正しいほうを選ぼう。\n(1)(2) The ( early ) you leave, the ( soon ) you will arrive.\n(3) Today is (very / much) colder than yesterday.', hint: '(1)(2) は the のあとに比較級が来る形、(3) は比較級の強調です。', steps: ['(1) early の比較級は earlier(y を i にかえて -er)。', '(2) soon の比較級は sooner。前半・後半どちらにも the がつく。', '(3) colder は比較級。比較級を強めるのは much で、very は使えない。'], a: '(1) earlier (2) sooner(早く出発すればするほど、早く着くだろう)(3) much(今日は昨日よりずっと寒い)', check: '(1)(2) は「早く出る」と「早く着く」が比例して変わる関係になっているかを確かめます。' }] },
      { h: '最上級の意味を表す比較級・原級', t: '「富士山は日本でいちばん高い山だ」は、最上級以外の形でも表せます。\n① Mt. Fuji is the highest mountain in Japan.(最上級)\n② Mt. Fuji is higher than any other mountain in Japan.(比較級 + than any other + 【単数名詞】)\n③ No other mountain in Japan is higher than Mt. Fuji.(No other + 単数名詞 + 比較級 than)/④ No other mountain in Japan is as high as Mt. Fuji.(No other + 単数名詞 + as 〜 as)\nany other の後ろが単数名詞になるのは、「ほかのどの1つの山と比べても」と1つずつ比べるからです(× any other mountains)。\nまた、【as 〜 as possible】(= as 〜 as S can)は「できるだけ〜」です。例:Please come as soon as possible.(できるだけ早く来てください)',
        key: '最上級は「比較級 + than any other + 単数名詞」「No other + 単数名詞 + 比較級 than」でも表せます。',
        ex: [{ q: '同じ意味になるように ( ) に適語を入れよう。\nTom is the tallest boy in his class.\n= Tom is ( ) than ( ) ( ) boy in his class.', hint: '「ほかのどの男子よりも背が高い」と言いかえます。', steps: ['最上級の文を「比較級 + than any other + 単数名詞」で書きかえる。', 'tall の比較級は taller。', 'than の後ろは any other、名詞は単数の boy のまま。'], a: 'taller / any / other(トムはクラスのほかのどの男子よりも背が高い)', check: 'No other boy in his class is taller than Tom. と書きかえても同じ意味になることを確かめます。' }] },
      { h: 'no more than / no less than', t: '【no + 比較級】の no は、「差がゼロ」という意味です。そこに話し手の気持ち(少ない・多い)が加わります。\n【no more than 〜】たった〜(= only)。「〜より多いことはまったくない」→ 少ないという気持ち。例:I have no more than 500 yen.(500円しか持っていない)\n【no less than 〜】〜も(= as much as / as many as)。「〜より少ないことはまったくない」→ 多いという気持ち。例:He has no less than 500 books.(彼は500冊も本を持っている)\nこれに対して not を使うと、単なる範囲を表します。【not more than 〜】多くても〜(= at most)/【not less than 〜】少なくとも〜(= at least)\nno は「強く打ち消して気持ちをこめる」、not は「ふつうに打ち消して範囲を示す」と考えると、区別しやすくなります。',
        key: 'no more than=たった(only)、no less than=〜も(as many/much as)。not more than=多くても、not less than=少なくとも。',
        ex: [{ q: '和訳しよう。\n(1) It took no more than ten minutes to get there.\n(2) No less than 3,000 people came to the concert.', hint: 'no more than は「少ない」、no less than は「多い」という気持ちをこめて訳します。', steps: ['(1) no more than=only(たった〜)。少ないという気持ち。', '(1) It took 〜 to …=…するのに〜かかった。to get there=そこに着くのに。', '(2) no less than=as many as(〜も)。多いという気持ち。'], a: '(1) そこに着くのに、たった10分しかかからなかった。(2) 3,000人もの人がそのコンサートに来た。', check: '(1) を only ten minutes、(2) を as many as 3,000 people に置きかえても意味が変わらないことを確かめます。' }] },
      { h: 'クジラの構文・no longer など', t: '【no longer】は「もはや〜ない」です。例:He no longer lives here.(彼はもうここに住んでいない)= He doesn\'t live here any longer.\n【A is no more B than C is D】は「A が B でないのは、C が D でないのと同じだ」という意味で、クジラの構文と呼ばれます。例:A whale is no more a fish than a horse is.(馬が魚でないのと同じように、クジラも魚ではない)\nなぜこの意味になるのでしょうか。no は「差がゼロ」でした。「クジラが魚である度合い」は、「馬が魚である度合い」と差がゼロ、つまり同じくらい「まったくない」ということです。\n訳すときは、than の後ろ(だれが見ても明らかにちがうこと)を先に訳し、「〜でないのと同じように」とつなぐと自然になります。\nほかに、【not so much A as B】(A というよりむしろ B)もよく出ます。例:He is not so much a scholar as a writer.(彼は学者というよりむしろ作家だ)',
        key: 'A is no more B than C is D は、than の後ろの「明らかにちがうこと」を先に訳し、「〜でないのと同じように A も B ではない」とします。',
        ex: [{ q: '和訳しよう。\nA bat is no more a bird than a rat is.', hint: 'than の後ろ(a rat is a bird ではない)から先に考えます。', steps: ['than の後ろ:a rat is(a bird)=ネズミが鳥である → これは明らかにありえない。', 'no more 〜 than … =「…が〜でないのと同じように」。', 'A bat is no more a bird=コウモリも鳥ではない。than の後ろから訳してつなぐ。'], a: 'ネズミが鳥でないのと同じように、コウモリも鳥ではない。', check: '「コウモリは鳥ではない」という、筆者が言いたい内容が訳の最後にきているかを確かめます。' }] }
    ],
    faq: [
      ['なぜ very で比較級を強められないの?', 'very は原級(tall、interesting)の程度を強める語で、比較級が表す「どれくらい差があるか」を表すことはできないからです。\n比較級には、差の大きさを表す much・far・even・a lot を使います。'],
      ['than の後ろは I と me のどちらが正しいの?', '書き言葉では、than の後ろに動詞が省略されていると考えて He is taller than I (am). とします。話し言葉では He is taller than me. もよく使われます。\n入試の書きかえでは、than I am のように動詞まで書くと安全です。'],
      ['the 比較級, the 比較級 の後ろの語順はどうなるの?', 'the 比較級を先頭に出し、その後ろに S + V を続けます。The more you read, the more you learn.(読めば読むほど、多くを学ぶ)\n比較級が名詞をともなうときは、名詞も一緒に前に出します。The more books you read, the more you learn.']
    ],
    terms: [['原級', '比較の変化をしていない、もとの形(tall)'], ['比較級', '2つを比べる形(taller、more 〜)'], ['最上級', '3つ以上の中でいちばんを表す形(tallest、most 〜)'], ['倍数表現', 'X times as 〜 as。2倍は twice、半分は half'], ['no more than', 'たった〜(= only)'], ['クジラの構文', 'A is no more B than C is D。C が D でないのと同じように、A も B ではない']],
    miss: ['three times as large as を、three times larger as のように混ぜてしまう。as 〜 as か 比較級 + than のどちらかにそろえます。', '比較級を very で強めてしまう。比較級の強調は much・far・even と覚えます。', 'than any other の後ろを複数名詞にしてしまう。「1つずつ比べる」ので単数名詞です。', 'no more than(たった)と not more than(多くても)を同じ意味だと思ってしまう。no は気持ち、not は範囲と区別します。'],
    sum: ['倍数は X times as 〜 as。2倍 twice、半分 half。', 'the 比較級, the 比較級=〜すればするほど…。', '比較級の強調は much・far・even(very は不可)。', '最上級は 比較級 + than any other + 単数名詞 などでも表せる。', 'no more than=only、no less than=as many(much) as。クジラの構文は than の後ろから訳す。'],
    next: '次は「仮定法」です。比較と同じく、形とその裏にある「話し手の気持ち」をセットで理解することが大切な単元です。'
  };

  // ===== 仮定法 =====
  L.e_h2 = {
    goal: '仮定法過去・仮定法過去完了を使い分け、I wish・as if・Without 〜・if の省略など、if を使わない仮定法も読み書きできるようになる。',
    intro: '「もし私が鳥だったら、あなたのところへ飛んでいけるのに」。現実にはありえないことを想像して言うとき、英語では【時制を1つ過去にずらす】というルールを使います。今のことなのに過去形、過去のことなのに過去完了形。この「ずらし」によって、「これは現実ではありませんよ」という合図を出すのが【仮定法】です。',
    pre: '【過去形】と【過去完了(had + 過去分詞)】の形をおさらいします。過去形は過去の出来事を、過去完了は「過去のある時点よりさらに前」を表す形でした。\n【助動詞の過去形】would・could・might は、will・can・may の過去形です。would は「〜するだろう」、could は「〜できるだろう」、might は「〜かもしれない」の意味で、仮定法の主節でよく使います。\n中学で習った If it rains tomorrow, I will stay home.(明日雨が降ったら家にいる)は、実際に起こりうることを言う文で、【直説法】といいます。\nこれに対して、現実にはありえないこと・現実とちがうことを想像して言う文が【仮定法】です。',
    secs: [
      { h: '仮定法過去:今の事実に反する想像', t: '【If + S + 動詞の過去形, S + would(could・might) + 原形】は、「(今)もし〜なら、…だろうに」という意味です。形は過去形ですが、内容は【今】のことです。\n例:If I were a bird, I could fly to you.(もし私が鳥なら、あなたのところへ飛んでいけるのに)\n例:If I had more money, I would buy a new computer.(もっとお金があれば、新しいパソコンを買うのに)→ 事実は「お金がないので買えない」。\nなぜ今のことなのに過去形を使うのでしょうか。過去形には「今から離れている」という感覚があり、それを「現実から離れている」という意味に使っているのです。\nbe動詞は、主語が I や he でも【were】を使うのが基本です(話し言葉では was も使われます)。',
        key: '今の事実に反する想像は「If + 過去形, would + 原形」。形は過去でも、内容は今のことです。',
        ex: [{ q: '( ) 内の語を正しい形にしよう。\nI don\'t know her phone number. If I ( know ) her phone number, I ( call ) her now.', hint: '前の文が「現実」です。現実とちがうことを想像する形にします。', steps: ['現実:今、電話番号を知らない。→ 今の事実に反する想像なので仮定法過去。', 'if 節は過去形 → know を knew にする。', '主節は would + 原形 → would call。'], a: 'knew / would call(彼女の電話番号を知っていれば、今電話するのに)', check: '仮定法の文を現実に戻すと「知らないので電話できない」となり、最初の文と合うことを確かめます。' }] },
      { h: '仮定法過去完了:過去の事実に反する想像', t: '【If + S + had + 過去分詞, S + would(could・might) + have + 過去分詞】は、「(あのとき)もし〜だったら、…だっただろうに」という意味です。\n今のことを過去形でずらしたのと同じように、過去のことは1つ前の過去完了にずらします。\n例:If I had studied harder, I would have passed the exam.(もっと勉強していたら、試験に合格しただろうに)→ 事実は「勉強しなかったので不合格だった」。\n主節の would have + 過去分詞は、助動詞の後ろに「過去」を表す have + 過去分詞をつけた形です。',
        key: '過去の事実に反する想像は「If + had + 過去分詞, would have + 過去分詞」です。',
        ex: [{ q: '( ) に入る正しい形を選ぼう。\nIf he had left home earlier, he ( ) the train.\n① would catch ② would have caught ③ will catch ④ caught', hint: 'if 節の形から、今への仮定か過去への仮定かを決めます。', steps: ['if 節が had left(had + 過去分詞)→ 過去の事実に反する仮定(仮定法過去完了)。', '主節も過去のこと(電車に間に合ったかどうか)で、now などの語はない。', '主節は would + have + 過去分詞。'], a: '② would have caught(もっと早く家を出ていたら、彼はその電車に間に合っただろうに)', check: '現実に戻すと「早く出なかったので、間に合わなかった」となり、過去の話で筋が通ることを確かめます。' }] },
      { h: '混合型:過去の仮定と今の結果', t: '「過去に〜していたら、今は…だろうに」と、if 節が過去、主節が今のことを表す【混合型】もあります。\nif 節は仮定法過去完了(had + 過去分詞)、主節は仮定法過去(would + 原形)になります。\n例:If I had taken the medicine last night, I would feel better now.(昨夜薬を飲んでいたら、今は気分がよいだろうに)\n主節に now・today などの「今」を表す語があることが目印です。',
        key: 'if 節が過去完了でも、主節に now などがあれば、主節は would + 原形(混合型)です。',
        ex: [{ q: '( ) 内の語を正しい形にしよう。\nIf he had not missed the train, he ( be ) here now.', hint: '主節の now に注目します。', steps: ['if 節は had not missed(had + 過去分詞)→ 過去の事実(電車に乗り遅れた)に反する仮定。', '主節には now があり、今のことを言っている → 今の事実に反する想像。', '主節は would + 原形 → would be。'], a: 'would be(彼が電車に乗り遅れていなければ、今ここにいるだろうに)', check: '現実に戻すと「乗り遅れたので、今ここにいない」となり、過去の原因と今の結果がつながっていることを確かめます。' }] },
      { h: 'I wish・as if・It is time', t: '【I wish + 仮定法】は「〜ならいいのに」という、実現しない願望です。今のことなら過去形、過去のことなら過去完了にします。例:I wish I could speak French.(フランス語が話せたらいいのに)/I wish I had known the truth.(真実を知っていたらよかったのに)\n【as if + 仮定法】は「まるで〜であるかのように」です。例:He talks as if he knew everything.(彼はまるで何でも知っているかのように話す)\n例:She looked as if she had seen a ghost.(彼女はまるで幽霊を見たかのような顔をしていた)→ 見たのは、looked よりも前のこと。\n【It is time + S + 過去形】は「もう〜してもよいころだ(まだしていない)」です。例:It is time you went to bed.(もう寝る時間ですよ)',
        key: 'I wish・as if の後ろは、今のことなら過去形、それより前のことなら過去完了にします。',
        ex: [{ q: 'I wish を使って、ほぼ同じ意味の文に書きかえよう。\n(1) I\'m sorry I can\'t speak French.\n(2) I\'m sorry I didn\'t study harder.', hint: '残念に思っている内容が、今のことか過去のことかを見ます。', steps: ['(1) 「今フランス語が話せない」のが残念 → 今の事実に反する願望 → 過去形。', '(1) can\'t speak の反対を過去形にして could speak。', '(2) 「(過去に)もっと勉強しなかった」のが残念 → 過去の事実に反する願望 → 過去完了。', '(2) didn\'t study の反対を過去完了にして had studied。'], a: '(1) I wish I could speak French.(フランス語が話せたらいいのに)(2) I wish I had studied harder.(もっと勉強しておけばよかった)', check: 'I wish の後ろが、もとの文と「肯定・否定が逆」になっているかを確かめます(can\'t → could、didn\'t → had)。' }] },
      { h: 'if を使わない仮定法:Without・But for', t: '【Without 〜 / But for 〜】は「〜がなければ(なかったら)」という意味で、if 節の代わりになります。主節の形を見て、今のことか過去のことかを判断します。\n例:Without your help, I would have failed.(あなたの助けがなかったら、失敗していただろう)= If it had not been for your help, …\n今のことなら If it were not for 〜(〜がなければ)を使います。例:If it were not for water, nothing could live.(水がなければ、何も生きられないだろう)\nWithout・But for の後ろには名詞を置きます。S + V の文は続けません。',
        key: 'Without 〜=If it were not for 〜(今)/ If it had not been for 〜(過去)。どちらかは主節の形で決めます。',
        ex: [{ q: 'if を使って書きかえよう。\nWithout his advice, I could not have succeeded.', hint: '主節の could not have succeeded が、今と過去のどちらを表しているかを見ます。', steps: ['主節が could not have succeeded(have + 過去分詞)→ 過去のことへの仮定。', '過去の「〜がなかったら」は If it had not been for 〜。', 'Without his advice を If it had not been for his advice にする。'], a: 'If it had not been for his advice, I could not have succeeded.(彼の助言がなかったら、私は成功できなかっただろう)', check: '現実に戻すと「助言があったので成功できた」となり、意味が通ることを確かめます。' }] },
      { h: 'if の省略と倒置、should・were to', t: '【if の省略と倒置】if を省くと、were・had・should が主語の前に出ます(疑問文と同じ語順)。\n例:Were I you, I would accept the offer.(= If I were you, …)(私があなたなら、その申し出を受けるだろう)\n例:Had I known it, I would have told you.(= If I had known it, …)(それを知っていたら、あなたに言っていただろう)\n【If S should 〜 / If S were to 〜】は、未来について「万一〜なら/仮に〜なら」と、可能性が低いことを想像する形です。例:If it should rain tomorrow, the game will be put off.(万一明日雨が降れば、試合は延期される)\nshould の文は、主節に will や命令文が来ることもあります。',
        key: 'Were・Had・Should で始まる文は、if が省略された仮定法です。',
        ex: [{ q: 'if を使わずに、同じ意味の文に書きかえよう。\nIf I had known the truth, I would have told you.', hint: 'if を消したら、had を主語の前に出します。', steps: ['if 節は If I had known the truth(仮定法過去完了)。', 'if を省略すると、had が主語 I の前に出る(倒置)。', 'If I had known → Had I known。主節はそのまま。'], a: 'Had I known the truth, I would have told you.(真実を知っていたら、あなたに言っていただろう)', check: '文頭の Had I known を If I had known に戻すと、もとの文と同じになることを確かめます。' }] }
    ],
    faq: [
      ['If I were 〜 の were は、なぜ was ではないの?', '仮定法では、「現実ではない」ことを示す特別な形として、主語に関係なく were を使うのが伝統的な決まりだからです。\n話し言葉では If I was 〜 も使われますが、入試や書き言葉では were を使いましょう。特に If I were you(私があなたなら)は決まった言い方です。'],
      ['If it rains と If it rained は、どうちがうの?', 'If it rains tomorrow は「明日雨が降ったら」と、実際に起こりうることを言う直説法です。\nIf it rained now(仮定法過去)は「(今)もし雨が降っていれば」と、現実とはちがうことを想像する言い方です。話し手が「現実ではない」と思っているかどうかで使い分けます。'],
      ['仮定法の would と、ふつうの would はどう見分けるの?', 'if 節(または Without・I wish など)に仮定の合図があるかを見ます。合図があれば仮定法の would(〜だろうに)です。\nHe said he would come.(彼は来ると言った)のように、時制の一致で will が would になっているだけの場合もあります。']
    ],
    terms: [['仮定法過去', 'If + 過去形, would + 原形。今の事実に反する想像'], ['仮定法過去完了', 'If + had + 過去分詞, would have + 過去分詞。過去の事実に反する想像'], ['混合型', 'if 節は過去完了、主節は would + 原形。過去の仮定と今の結果'], ['倒置', 'if を省いたとき、Were・Had・Should を主語の前に出す形'], ['直説法', '現実のことをそのまま述べる、ふつうの言い方'], ['If it were not for 〜', '(今)〜がなければ。過去なら If it had not been for 〜']],
    miss: ['仮定法過去の文を「過去のこと」と訳してしまう。形は過去でも内容は今のことだと確かめます。', 'If I had studied … I would pass the exam. のように、if 節と主節の時をずらしてしまう。混合型は now などの目印があるときだけです。', 'Without の後ろに文(S + V)を続けてしまう。Without の後ろは名詞です。', 'if を省いたのに倒置を忘れて、I had known it, … としてしまう。Had を主語の前に出します。'],
    sum: ['仮定法は「時制を1つ過去にずらす」=現実ではないという合図。', '今への仮定は過去形、過去への仮定は過去完了。主節に now があれば混合型。', 'I wish・as if の後ろも、今なら過去形、過去なら過去完了。', 'Without 〜 / But for 〜 / If it were not for 〜 / If it had not been for 〜。', 'if を省くと Were・Had・Should が文頭に出る。'],
    next: '次は「強調・倒置・省略・挿入・話法」です。仮定法で学んだ「if の省略と倒置」を、否定語の倒置など、ほかの倒置の形と合わせて整理できます。'
  };

  // ===== 強調・倒置・省略・挿入・話法 =====
  L.e_emph = {
    goal: '強調構文・倒置・省略・挿入を見抜いて正しく訳し、直接話法と間接話法を書きかえられるようになる。',
    intro: '英語の文は、ふつうは S + V の語順です。ところが、言いたいことを目立たせたいときや、くり返しを避けたいときには、語順を入れかえたり、語を省いたりします。こうした「ふつうでない形」に出会うと、文の骨組みが見えにくくなります。この単元では、その形の決まりを知り、もとのふつうの文に戻して読めるようにします。',
    pre: '英語のふつうの語順は【S + V】です。疑問文になると、【助動詞・be動詞 + S + V】のように、助動詞や be動詞が主語の前に出ます。例:Have you ever seen it? / Did you go there? / Is he busy?\n【形式主語の It】は、長い主語を後ろに回すための仮の主語です。It is important to study every day.(毎日勉強することは大切だ)では、It が to study every day を指しています。\n【引用符(" ")】は、人が言ったことばをそのまま書くときに使う記号です。例:He said, "I am busy."(彼は「私は忙しい」と言った)\n【時制の一致】は、主節の動詞が過去のとき、that 節などの動詞もそれに合わせて過去の形にすることでした。I think he is busy. → I thought he was busy.',
    secs: [
      { h: '強調構文 It is 〜 that …', t: '文の中の1つの語句を目立たせたいとき、【It is(was)+ 強調したい語句 + that …】の形にします。「…なのは〜だ」と訳します。\nもとの文:Ken broke the window yesterday.\n→ It was Ken that broke the window yesterday.(昨日窓を割ったのはケンだった)\n→ It was the window that Ken broke yesterday.(昨日ケンが割ったのは窓だった)/It was yesterday that Ken broke the window.(ケンが窓を割ったのは昨日だった)\n強調する語句が人なら that の代わりに who、物なら which を使うこともあります。\n【見分け方】It is(was)と that を取り除いてみます。残りがそのまま完全な文になれば強調構文です。\n例:It is true that he broke the window. → true he broke the window は文にならない → これは強調構文ではなく、It が that 以下を指す【形式主語】の文です。',
        key: 'It is と that を取り除いて完全な文に戻れば強調構文、戻らなければ形式主語の文です。',
        ex: [{ q: '次の文は強調構文か、形式主語の文か。和訳もしよう。\n(1) It was in this park that I first met her.\n(2) It is important that we keep our promises.', hint: 'It was(is)と that を消して、残りが文になるかを確かめます。', steps: ['(1) It was と that を取り除く → in this park I first met her → I first met her in this park. という完全な文になる → 強調構文。', '(1) 強調されているのは in this park。「…したのは〜だ」と訳す。', '(2) It is と that を取り除く → important we keep our promises → 文にならない → 形式主語。', '(2) It は that 以下(約束を守ること)を指す。'], a: '(1) 強調構文:私が初めて彼女に会ったのは、この公園だった。(2) 形式主語:約束を守ることは大切だ。', check: '(2) は To keep our promises is important. と言いかえられることでも、形式主語の文だと確かめられます。' }] },
      { h: '否定語が文頭に来ると倒置', t: '【Never・Little・Hardly・Not only・Only + 副詞(句)】などの否定・限定の語句を文頭に出して強調すると、その後ろは【疑問文と同じ語順】(助動詞・be動詞 + S)になります。\n例:I have never seen such a beautiful sunset. → Never have I seen such a beautiful sunset.(こんなに美しい夕日は見たことがない)\n一般動詞の文では、do・does・did を主語の前に出します。例:I little dreamed that I would win. → Little did I dream that I would win.(自分が勝つとは夢にも思わなかった)\n例:Not only did he sing, but he also danced.(彼は歌っただけでなく、踊りもした)\n例:Only then did I realize my mistake.(そのとき初めて、自分のまちがいに気づいた)\n否定語を前に出すと「強調の合図」になり、後ろが疑問文の語順になることで、読む人に「ふつうの文ではない」と知らせているのです。',
        key: '否定語・Only 〜 が文頭に来たら、後ろは疑問文の語順(助動詞・be動詞 + S)になります。',
        ex: [{ q: 'Never で始めて、同じ意味の文に書きかえよう。\nI have never heard such a strange story.', hint: 'Never を文頭に出したら、後ろを疑問文の語順にします。', steps: ['否定語 never を文頭に出す。', '後ろは疑問文の語順 → 助動詞 have を主語 I の前に出す。', 'Never have I heard such a strange story.'], a: 'Never have I heard such a strange story.(こんなに奇妙な話は聞いたことがない)', check: 'Have I heard such a strange story? という疑問文の語順と、Never の後ろの語順が同じになっているかを確かめます。' }] },
      { h: 'No sooner 〜 than・So do I などの倒置', t: '【No sooner had S + 過去分詞 than 〜】【Hardly(Scarcely)had S + 過去分詞 when(before)〜】は「…するとすぐに〜」の意味です。\n例:No sooner had I left home than it began to rain.(家を出たとたんに雨が降りだした)\n家を出たのが先なので、前半は過去完了、後半は過去形になります。No sooner には than、Hardly には when を組み合わせる点にも注意します。\nほかに、【So + 助動詞・be動詞 + S】(S もそうだ)、【Neither(Nor)+ 助動詞・be動詞 + S】(S もそうではない)も倒置です。\n例:"I like cats." "So do I."(「ねこが好きです」「私もです」)/"I can\'t swim." "Neither can I."(「泳げません」「私もです」)',
        ex: [{ q: '( ) に適語を入れよう。\n(1) "I didn\'t like the movie." "( ) did I."\n(2) No sooner had he sat down ( ) the phone rang.', hint: '(1) は前の文が否定文かどうか、(2) は No sooner と組む語を考えます。', steps: ['(1) 前の文は didn\'t を使った否定文。「私もそうではない」は Neither(Nor)+ 助動詞 + S。', '(1) 過去の一般動詞の文なので did を使い、Neither did I。', '(2) No sooner 〜 は than と組み合わせて「〜するとすぐに」。'], a: '(1) Neither(または Nor)(「その映画は好きではなかった」「私もです」)(2) than(彼が座ったとたんに、電話が鳴った)', check: '(1) で So did I. とすると「私も好きだった」という逆の意味になってしまうことを確かめます。' }] },
      { h: '省略と挿入', t: '【省略】くり返しになる語や、言わなくても分かる語は省かれます。\n時・条件などの副詞節で、主語が主節と同じとき、【S + be動詞】がよく省かれます。例:When (I was) young, I lived in Kobe.(若いころ、神戸に住んでいた)/Fill in this form if (it is) necessary.(必要なら、この用紙に記入してください)\n前に出た動詞のくり返しも省かれます。例:You can go if you want to (go).(行きたいなら行っていいよ)\n【挿入】文の途中に、コンマやダッシュではさんで語句が入ることがあります。例:He is, I think, the best player on the team.(彼は、私が思うに、チームでいちばんの選手だ)\n挿入部分をいったんかっこでくくって外すと、文の骨組み(He is the best player)が見えます。',
        key: '省略は省かれた語を補って読み、挿入はかっこでくくって外してから骨組みを確かめます。' },
      { h: '話法の転換', t: '人の言葉を引用符(" ")でそのまま伝えるのが【直接話法】、自分の言葉に直して伝えるのが【間接話法】です。間接話法にするときは、次の3つを変えます。\n① 【代名詞】を、伝える人の立場に合わせる(I → he・she など)。\n② 【時制】を、伝える動詞が過去なら1つ過去にずらす(現在 → 過去、過去・現在完了 → 過去完了、will → would)。\n③ 【時・場所の語】を変える:now → then、today → that day、tomorrow → the next day、yesterday → the day before、ago → before、here → there、this → that\n例:He said to me, "I will help you tomorrow." → He told me (that) he would help me the next day.(彼は翌日私を手伝うと言った)\n疑問文は【ask + 疑問詞(または if)+ S + V】にします。例:She said to me, "Where do you live?" → She asked me where I lived.\n命令文は【tell + 人 + to 不定詞】、ていねいな依頼(Please 〜)は【ask + 人 + to 不定詞】にします。例:He said to me, "Open the window." → He told me to open the window.',
        key: '間接話法では、代名詞・時制・時と場所の語の3つを、伝える人の立場に合わせて変えます。',
        ex: [{ q: '間接話法に書きかえよう。\nMy mother said to me, "Are you hungry now?"', hint: '疑問詞のない疑問文は if(whether)を使います。', steps: ['疑問詞のない疑問文 → asked me if(whether)〜。', '代名詞:you は「私」のこと → I。', '時制:said が過去なので are → was。now → then。', '語順は「if + S + V」(疑問文の語順にしない)。'], a: 'My mother asked me if I was hungry then.(母は私に、そのときおなかがすいているかとたずねた)', check: 'if の後ろが I was の順になっていて、was I になっていないことを確かめます。' },
          { q: '間接話法に書きかえよう。\nHe said to me, "Please wait here."', hint: 'Please がついたていねいな依頼は、ask + 人 + to 不定詞にします。', steps: ['Please 〜 はていねいな依頼 → asked me to 〜。', '命令文の動詞 wait は、to 不定詞 to wait にする。', '場所の語:here → there。'], a: 'He asked me to wait there.(彼は私に、そこで待つように頼んだ)', check: 'もとの文の「頼む」という気持ちが asked で表されていて、here が there に変わっているかを確かめます。' }] }
    ],
    faq: [
      ['強調構文の that を who に変えてもいいの?', '強調される語句が人のときは who、物のときは which を使うこともできます。It was Ken who broke the window. も正しい文です。\nただし、時や場所(yesterday、in this park)を強調するときは、ふつう that を使います。'],
      ['倒置はなぜ起こるの?', '主な理由は2つです。1つは、否定語などを文頭に出して強調したいとき。もう1つは、長い主語を文の後ろに回して読みやすくしたいときです。\nどちらの場合も、もとの語順に戻して考えると意味がとりやすくなります。'],
      ['間接話法で、時制を変えなくてよいときはあるの?', 'あります。伝える動詞が現在形(He says 〜)のときは、時制は変えません。また、いつでも変わらない真理などは、過去にしなくてもよいとされています。\n例:The teacher said that the earth goes around the sun.(先生は、地球は太陽のまわりを回っていると言った)']
    ],
    terms: [['強調構文', 'It is 〜 that …。〜の部分を目立たせる'], ['形式主語', 'It を仮の主語にして、本当の主語(that 節・to 不定詞)を後ろに置く形'], ['倒置', '強調などのために、ふつうの語順(S + V)を入れかえること'], ['挿入', '文の途中に、コンマやダッシュではさんで語句を入れること'], ['直接話法', '人の言葉を " " でそのまま伝える方法'], ['間接話法', '人の言葉を、伝える人の立場から言い直して伝える方法']],
    miss: ['強調構文と形式主語の文を区別せずに訳してしまう。It is と that を外して、完全な文に戻るかを確かめます。', 'Never I have seen … のように、否定語を文頭に出したのに倒置を忘れる。否定語の後ろは疑問文の語順です。', '間接話法の疑問文で、She asked me where did I live. と疑問文の語順を残してしまう。間接疑問は S + V の順です。', '間接話法で、tomorrow や here をそのまま残してしまう。伝える人の立場から見た語(the next day・there)に変えます。'],
    sum: ['強調構文は、It is と that を外すと完全な文に戻る。', '否定語・Only 〜 が文頭に来たら、疑問文の語順(倒置)。', 'No sooner 〜 than、Hardly 〜 when は「〜するとすぐに」。', '副詞節の S + be動詞 は省略されやすい。挿入はかっこでくくって外す。', '間接話法は 代名詞・時制・時と場所の語 の3つを変える。'],
    next: '次は「入試レベル:英文法・語法の総合」です。ここまで学んだ時制・仮定法・関係詞・準動詞・比較・倒置を、入試の問題形式で組み合わせて使う練習をします。'
  };

  // ===== 入試レベル =====
  L.ex_eng = {
    goal: '時制・仮定法・関係詞・準動詞・比較が組み合わさった入試の文法問題を、「骨格 → 空所の働き → 文法項目」の順で解けるようになる。',
    intro: '入試の文法・語法問題は、1問の中に複数の文法事項が重なっていることがよくあります。空所の前後の2〜3語だけを見て選ぶと、ひっかけの選択肢にだまされます。どんな問題でも、【文全体の骨組み(S と V)を先に見つける】ことから始めれば、正解の根拠がはっきりします。この単元では、高校で学ぶ文法の要点を総復習しながら、入試での解き方の型を身につけます。',
    pre: 'この単元は、高校で学ぶ英文法の総まとめです。読む前に、次の項目をざっと思い出しておきましょう。\n【5文型】英文の骨組みは S・V・O・C で、M(修飾語)は文型に数えません。前置詞+名詞のかたまりは M です。\n【時制】完了形は「基準の時点」で選びます(今=have、過去=had、未来=will have)。時・条件の副詞節の中は、未来でも現在形です。\n【仮定法】今への仮定は過去形、過去への仮定は過去完了。【関係詞】後ろが完全なら関係副詞、不完全なら関係代名詞。【分詞】名詞が「する」側なら〜ing、「される」側なら過去分詞。\n自信のない項目があれば、先にその単元を読み直してから進むと効果的です。',
    secs: [
      { h: '解き方の型(4ステップ)', t: '① 【文の骨格を見つける】主節の S と V に印をつけます。接続詞・関係詞のかたまりはかっこでくくります。\n② 【空所の働きを決める】空所が S・V・O・C・M のどれにあたるか、品詞は何か(名詞・形容詞・副詞・動詞)を決めます。\n③ 【文法項目を特定する】選択肢を見て、何がテーマの問題か(時制・仮定法・関係詞・準動詞・比較・語法)を判断します。\n④ 【根拠となる語を探す】時を表す語、if、先行詞、主語との関係など、答えを決める「目印」を文中から見つけ、それを根拠に選びます。\n選んだら、最後に全文を訳して意味が通るか確かめます。\nこの順番が大切なのは、①②で「入りえない選択肢」を先に消せるからです。V がすでにある文なら、V になる選択肢は入りません。',
        key: '骨格(S・V)→ 空所の働き(品詞)→ 文法項目 → 根拠の語、の順に考え、最後に全文を訳して確かめます。',
        ex: [{ q: '( ) に入る最も適切なものを選ぼう。\nI am looking forward ( ) you again.\n① to see ② to seeing ③ seeing ④ see', hint: 'look forward to の to が、前置詞か不定詞の to かを考えます。', steps: ['骨格:S=I、V=am looking。空所以下は looking forward につながる部分。', '文法項目:熟語 look forward to 〜(〜を楽しみに待つ)の語法。', '根拠:この to は前置詞なので、後ろは名詞か動名詞。', 'よって to seeing。③ は to がなく、① と ④ は原形なので不可。'], a: '② to seeing(またあなたに会えるのを楽しみにしています)', check: 'to の後ろに名詞を入れて I am looking forward to the party. と言えることから、to が前置詞だと確かめられます。' }] },
      { h: '時制の目印', t: '時制の問題では、次の目印が決め手になります。\nby the time + 過去 / when + 過去 で「それより前」なら → 過去完了(had + 過去分詞)\nby + 未来の時点 / by the time + 現在形 → 未来完了(will have + 過去分詞)\nsince 〜 / for 〜 で「今まで」 → 現在完了。yesterday・〜 ago など、はっきりした過去の時 → 過去形\n時・条件の副詞節(if・when・as soon as など)→ 未来でも現在形。「〜かどうか」の if 節(名詞節)→ will\n目印を見つけたら、時間の線を書いて、基準の時点がどこにあるかを確かめると確実です。',
        key: '時制は「基準の時点」がどこか(今・過去・未来)を目印の語から決めます。',
        ex: [{ q: '( ) に入る最も適切なものを選ぼう。\nI ( ) in this town for ten years next April.\n① will have lived ② have lived ③ lived ④ live', hint: '基準の時点を表す語と、期間を表す語を探します。', steps: ['骨格:S=I、V=空所。空所には時制をもつ動詞が入る。', '根拠の語:next April(来年の4月)は未来の基準点、for ten years は継続の目印。', '未来の時点までの継続 → 未来完了 will have + 過去分詞。', '② は今が基準なので next April と合わない。'], a: '① will have lived(来年の4月で、この町に住んで10年になる)', check: '時間の線に「住み始めた → 今 → 来年4月(10年)」と並べ、基準点が未来にあることを確かめます。' }] },
      { h: '仮定法・提案の that 節の目印', t: '仮定法の問題では、if 節と主節の形がセットになっています。\n主節に would have + 過去分詞 → if 節は had + 過去分詞。if 節が過去完了でも、主節に now・today があれば → 混合型(would + 原形)\n文頭の Were・Had・Should → if が省略された仮定法。Without 〜・But for 〜 → 主節の形で今か過去かを決める\n【提案・要求の that 節】suggest・insist・demand・propose・recommend などの後ろの that 節では、動詞は【(should +)原形】になります。主語が3人称単数でも -s をつけず、主節が過去でも過去形にしません。\n例:I suggested that he see a doctor.(私は彼に医者にみてもらうよう提案した)',
        key: '提案・要求の動詞(suggest・demand など)の that 節は、主語や時制に関係なく (should +) 原形です。',
        ex: [{ q: '( ) に入る最も適切なものを選ぼう。\nThe doctor recommended that my father ( ) smoking.\n① stops ② stop ③ stopped ④ will stop', hint: 'recommend がどんな意味の動詞かに注目します。', steps: ['骨格:S=The doctor、V=recommended。that 以下は recommended の O。', 'recommend(〜を勧める)は提案・要求の動詞 → that 節の動詞は (should +) 原形。', '主語 my father は3人称単数だが、原形なので -s はつかない。', 'stopped(過去形)や stops は、時制の一致や3単現にひっかけた選択肢。'], a: '② stop(医者は父に禁煙するよう勧めた)', check: 'that my father should stop smoking と should を補っても文が成り立つことを確かめます。' }] },
      { h: '関係詞・準動詞の目印', t: '【関係詞】後ろの文が完全か不完全かで決めます。不完全(S・O が欠ける)なら関係代名詞(who・which・that・what)、完全なら関係副詞(where・when・why)か接続詞 that です。\n先行詞がなければ what、コンマの後なら that は使えません。\n【準動詞】動詞の語法では、want・decide は to 不定詞、enjoy・avoid・finish は動名詞をとります。\n分詞・分詞構文では、主語(説明される名詞)が「する」側なら〜ing、「される」側なら過去分詞を選びます。\n使役では、make・let・have は O + 原形、get は O + to 不定詞をとります。\nまた、文の中に V がすでにあるときは、空所に入るのは V ではなく、準動詞(不定詞・分詞)か関係詞のかたまりです。',
        key: '文に V がすでにあれば、空所は V ではありません。準動詞・関係詞のどれが入るかを、名詞との関係で決めます。',
        ex: [{ q: '( ) に入る最も適切なものを選ぼう。\nThe language ( ) in this country is similar to Spanish.\n① speaking ② spoken ③ is spoken ④ to speak', hint: 'まず文の V を探して、空所が V かどうかを決めます。', steps: ['骨格:S=The language、V=is(similar)。動詞はすでにあるので、③ is spoken を入れると V が2つになり不可。', '空所以下 ( ) in this country は The language を後ろから説明する形容詞のかたまり → 分詞。', '言語は人に「話される」側 → 受動 → 過去分詞。'], a: '② spoken(この国で話されている言語は、スペイン語に似ている)', check: '「The language is spoken in this country.」と、名詞を主語にした受動態の文が成り立つことを確かめます。' }] },
      { h: '比較・語法の目印', t: '【比較】as 〜 as の間は原級、than の前は比較級です。比較級の強調は much・far・even で、very は使えません。\nthan any other の後ろは単数名詞、倍数は X times as 〜 as、the 比較級, the 比較級 は後半にも the が必要です。\n【まぎらわしい動詞の語法】自動詞と他動詞の lie(横になる)/lay(〜を置く)、rise(上がる)/raise(〜を上げる)。前置詞が不要な他動詞の discuss・marry・enter・reach・approach。\n「貸す・借りる」は、lend(貸す)、borrow(借りる)、rent(お金を払って貸し借りする)。\n「言う」は、say(言葉を言う)、tell + 人(人に伝える)、talk・speak(話す。talk to 人)です。',
        ex: [{ q: '( ) に入る最も適切なものを選ぼう。\n(1) This bridge is ( ) longer than that one. ① very ② much ③ more ④ many\n(2) Could you ( ) me your dictionary? ① borrow ② lend ③ say ④ talk', hint: '(1) は比較級の強調、(2) は me と your dictionary の2つの O をとれる動詞を考えます。', steps: ['(1) longer は比較級。比較級を強めるのは much で、very は使えない。more longer は比較級を重ねていて誤り。', '(2) 空所の後ろに me(人)と your dictionary(物)が並ぶ → SVOO をとる動詞。', '(2) 「私に辞書を貸す」は lend。borrow は「借りる」で、borrow A from B の形をとる。'], a: '(1) ② much(この橋はあの橋よりずっと長い)(2) ② lend(辞書を貸していただけませんか)', check: '(2) を borrow で言うなら Could I borrow your dictionary? のように主語が変わることを確かめます。' }] },
      { h: '複数の文法事項が重なった問題', t: '難しい問題ほど、1つの空所に2つ以上の文法事項がからんでいます。そのときも、4ステップを順番に当てはめれば答えが決まります。\nたとえば、文頭が Had で始まる文は、if が省略された仮定法過去完了です。その場合、主節は would have + 過去分詞になる、と「目印 → 形」を順につなげます。\n関係詞の直後に I think・I believe・I thought などが続くときは、それをかっこでくくってから、関係詞が後ろの節で何の役割をしているかを決めます(連鎖関係代名詞)。\n例:The man who I thought was honest deceived me.(私が正直だと思っていた男は、私をだました)→ (I thought) をくくると who was honest となり、who は was の主語(主格)です。\n最後に、選んだ答えを入れて全文を訳し、意味が自然かどうかを必ず確かめます。訳がおかしければ、どこかのステップでまちがえています。',
        key: '関係詞の直後の I think などはかっこでくくり、関係詞が後ろの節の S か O かを決めます。',
        ex: [{ q: '( ) に入る最も適切なものを選ぼう。\nThe woman ( ) I believed was my friend told my secret to everyone.\n① who ② whom ③ which ④ what', hint: '( ) の直後の I believed をかっこでくくってみます。', steps: ['骨格:S=The woman、V=told。( ) I believed was my friend は The woman を説明する関係詞節。', '(I believed) をかっこでくくると、( ) was my friend が残る。', '( ) は was の主語 → 主格。先行詞 The woman は人なので who。', 'whom は目的格なので、I believed の目的語だと考えたひっかけ。'], a: '① who(私が友達だと信じていた女性は、私の秘密をみんなに話してしまった)', check: 'I believed (that) she was my friend. と元の文に戻すと、she(主格)の位置に関係詞が入っていることを確かめます。' }] }
    ],
    faq: [
      ['文法問題は、全部の文を訳さないと解けないの?', '全文をていねいに訳す必要はありませんが、骨格(S と V)と空所のはたらきは必ず確かめます。前後の2〜3語だけで選ぶと、ひっかけの選択肢にだまされやすくなります。\n答えを選んだあとに、ざっと全体を訳して確かめるのがいちばん確実です。'],
      ['提案の that 節で should が省略されるのはなぜ?', 'もともと that he should see a doctor のように should が入っていた形から、should が省かれて原形だけが残った、と考えると覚えやすいです(特にアメリカ英語では原形だけの形がふつうです)。\nどちらの形でも、動詞は原形になります。'],
      ['知らない文法事項が出たらどうするの?', '4ステップのうち、①骨格と②空所の品詞を決めるだけでも、選択肢をかなりしぼれます。V がすでにある文なら V になる選択肢を消す、前置詞の後ろなら動詞の原形を消す、のように、消去法で考えましょう。']
    ],
    terms: [['骨格', '文の中心になる主節の S と V'], ['空所の働き', '空所が文の中で S・V・O・C・M のどれにあたるか'], ['提案・要求の that 節', 'suggest・insist などの後ろの that 節。動詞は (should +) 原形'], ['連鎖関係代名詞', '関係代名詞の後ろに I think などがはさまる形'], ['消去法', '文の構造から、入りえない選択肢を先に消していく解き方']],
    miss: ['空所の前後だけを見て、文の中に V がすでにあるのにもう1つ V を入れてしまう。最初に主節の V に印をつけます。', 'suggest that he sees のように、提案の that 節で -s をつけてしまう。should を補って原形になるかを確かめます。', '連鎖関係代名詞で、I thought の目的語だと考えて whom を選んでしまう。I thought をかっこでくくってから判断します。', '答えを選んだあとに全文を訳して確かめず、意味の通らない文のままにする。最後の確認を習慣にします。'],
    sum: ['まず主節の S と V を見つけ、かたまりをかっこでくくる。', '空所の働き(品詞)→ 文法項目 → 根拠の語 の順に考える。', '時制は「基準の時点」、関係詞は「後ろの文が完全か」、分詞は「能動か受動か」が決め手。', '提案・要求の that 節は (should +) 原形。', '最後に全文を訳して確かめる。'],
    next: '次は「難関レベル:英語」です。並べかえ・同格・補語の倒置など、文の構造をさらに深く見抜く力が問われる問題に進みましょう。'
  };

  // ===== 難関レベル =====
  L.hd_eng = {
    goal: '難関大の英語で問われる並べかえ・倒置・挿入・同格・細かい語法・難しい単語に、手順をもって対応できるようになる。',
    intro: '難関大の英語では、知識の量だけでなく【文の構造を見抜く力】が問われます。並べかえ問題も、長文の下線部和訳も、根っこは同じで、「どれが主語で、どれが動詞か」を正確に決められるかどうかです。この単元では、難しい問題に共通する考え方の型と、よく狙われる語法・構文をまとめます。',
    pre: '【5文型】と【自動詞・他動詞】をおさらいします。他動詞は後ろに O をとり、O の後ろにさらに何をとるか(SVOO・SVOC、to 不定詞、from 〜ing など)は動詞ごとに決まっています。これを動詞の【語法】といいます。\n【関係代名詞の that】の後ろは、S や O が欠けた不完全な文になりました。一方、【接続詞の that】の後ろは、完全な文になります。\n【倒置】は、否定語を文頭に出したときなどに、ふつうの S + V の語順が入れかわることでした。例:Never have I seen such a thing.\n【接頭辞・接尾辞】は単語の前後につく部品で、un-(否定)、re-(再び)、-tion(名詞を作る)、-able(〜できる)などがあります。',
    secs: [
      { h: '並べかえ問題の手順', t: '並べかえは、語を1つずつ順番に置いていくと必ず迷います。次の順に考えます。\n① 【動詞を決める】選択肢の中から、主節の V になれる語(時制のある動詞)を探します。② 【主語を決める】その V の主語(S)を決めます。\n③ 【かたまりを作る】前置詞 + 名詞、to 不定詞、関係詞節、熟語(prevent A from 〜 など)を、意味のかたまりにまとめます。\n④ 【文型にあてはめる】V の語法(SVO か SVOC か、後ろに何をとるか)に合わせて、かたまりを並べます。⑤ 日本語と照らし合わせて確認します。\nなぜ V から考えるのでしょうか。英文の形は V の語法でほぼ決まるので、V が決まれば、後ろに何がどの順で来るかが見えるからです。\n日本語の語順にひきずられないことが大切です。日本語の「〜のせいで」が、英語では主語になることもあります。',
        key: '並べかえは V → S → かたまり → 文型(V の語法)の順。日本語の語順にひきずられないようにします。',
        ex: [{ q: '日本語に合うように並べかえよう。\n「その事故のせいで、私たちは時間どおりに到着できなかった。」\nThe accident ( arriving / from / prevented / us ) on time.', hint: '時制をもつ動詞を1つ探し、その動詞の語法を思い出します。', steps: ['動詞を決める:時制のある動詞は prevented。主語は The accident。', '語法:prevent A from 〜ing=A が〜するのを妨げる。', 'かたまり:prevented + us + from + arriving。', '直訳「その事故は私たちが時間どおりに到着するのを妨げた」→ 日本語と意味が合う。'], a: 'The accident prevented us from arriving on time.', check: '日本語の「〜のせいで」が英語では主語(The accident)になっている、という発想の切りかえができているかを確かめます。' }] },
      { h: '補語の倒置と挿入', t: '【倒置】否定語の倒置(Never have I …)のほかに、補語を文頭に出す倒置もあります。\n例:Happy is the man who has true friends.(本当の友人がいる人は幸せだ)→ もとは The man who has true friends is happy.\n長い主語を後ろに回すために、C + V + S の語順になっています。英語には「長い要素は後ろに置く」という傾向があるからです。\n【挿入】コンマ・ダッシュではさまれた部分をかっこでくくると、骨格が見えます。例:The plan, it seems, has failed.(その計画は、どうやら失敗したようだ)',
        key: '文頭が形容詞・過去分詞で、後ろに V + S が続くときは補語の倒置。もとの S + V + C に戻して読みます。',
        ex: [{ q: '文の S・V・C を答え、和訳しよう。\nGone are the days when we could swim in this river.', hint: '文頭の Gone は過去分詞です。be動詞 are の主語を後ろから探します。', steps: ['V は are。are の後ろの the days (when we could swim in this river) が S。', '文頭の Gone(過ぎ去った)が C。C + V + S の補語の倒置。', 'もとの語順:The days when we could swim in this river are gone.', 'when 以下は the days を説明する関係副詞の節。'], a: 'S=the days(when 〜 river)、V=are、C=Gone。訳:この川で泳ぐことができた日々は、過ぎ去ってしまった。', check: 'もとの語順の文に戻したとき、S(the days …)と V(are)の数が一致しているか(複数 → are)を確かめます。' }] },
      { h: '同格の that と関係代名詞の that', t: '【同格の that】は、名詞の後ろの that 節が、その名詞の【内容】を説明する形です。fact・news・idea・belief・possibility などの後ろによく来ます。\n関係代名詞の that と見分けるには、【後ろの文が完全か】を確かめます。\n完全な文なら同格の that です。例:The fact that he was absent surprised me.(彼が欠席したという事実は、私を驚かせた)\n不完全な文なら関係代名詞です。例:The fact that he told me was surprising.(彼が私に話した事実は驚くべきものだった)→ told me の後ろの O が欠けている\n訳し方も、同格は「〜という(名詞)」、関係代名詞は「〜する(名詞)」とちがいます。',
        key: '名詞 + that 節は、後ろが完全な文なら同格(〜という)、不完全なら関係代名詞(〜する)です。',
        ex: [{ q: '次の文の that は「同格」か「関係代名詞」か。和訳もしよう。\n(1) There is no possibility that he will win the race.\n(2) The idea that she suggested was rejected.', hint: 'that の後ろに、S や O の欠けがあるかを確かめます。', steps: ['(1) that の後ろ:he will win the race → S・V・O がそろった完全な文 → 同格。', '(1) possibility の内容(彼がレースに勝つこと)を説明している。', '(2) that の後ろ:she suggested → suggest の O が欠けた不完全な文 → 関係代名詞。'], a: '(1) 同格(彼がレースに勝つ可能性はない)(2) 関係代名詞(彼女が提案した考えは却下された)', check: '(2) の that を which に置きかえても文が成り立つことで、関係代名詞だと確かめられます(同格の that は which にできません)。' }] },
      { h: 'ねらわれやすい語法', t: '【A of B の形をとる動詞】rob A of B(A から B を奪う)、deprive A of B(A から B を奪う)、remind A of B(A に B を思い出させる)、inform A of B(A に B を知らせる)。例:The man robbed her of her bag.(その男は彼女からかばんを奪った)\nこれに対して steal は、steal B (from A)(A から B を盗む)の形です。rob は「人」を、steal は「物」を O にとります。\n【A from 〜ing の形をとる動詞】prevent・keep・stop A from 〜ing(A が〜するのを妨げる)\n【cost と take】It costs + 人 + 金額 + to 〜(〜するのに〈お金〉がかかる)、It takes + 人 + 時間 + to 〜(〜するのに〈時間〉がかかる)\n【make・let・have と get】使役の make・let・have は O + 原形、get は O + to 不定詞をとります。例:My father let me use his car.(父は私に車を使わせてくれた)/I got my brother to help me.(弟に手伝ってもらった)',
        key: 'rob は「人 of 物」、steal は「物 from 人」。cost はお金、take は時間。語法は形ごと覚えます。',
        ex: [{ q: '次の文の誤りを直そう。\n(1) The man stole her of her bag.\n(2) It took me 3,000 yen to fix my bike.', hint: '(1) は steal が何を O にとるか、(2) はお金か時間かを考えます。', steps: ['(1) steal は「物」を O にとり、steal B from A の形。「人 of 物」の形をとるのは rob。', '(1) stole を robbed にするか、The man stole her bag (from her). にする。', '(2) 3,000 yen はお金なので、take ではなく cost を使う。', '(2) cost の過去形は cost(cost - cost - cost)なので、It cost me 3,000 yen to fix my bike.'], a: '(1) The man robbed her of her bag.(または The man stole her bag.)(その男は彼女からかばんを奪った)(2) It cost me 3,000 yen to fix my bike.(自転車を修理するのに3,000円かかった)', check: '(2) は cost の過去形が costed にならないこと、主語の It が to fix 以下を指していることを確かめます。' }] },
      { h: '難しい単語への対応', t: '難関大の長文には、英検準1級レベルの単語がふくまれます。すべてを覚えることはできないので、次の2つで対応します。\n【語の部品から推測する】un-・in-・im-・dis-(否定):unavoidable(避けられない)、inevitable(避けられない)、dishonest(不正直な)。pre-(前に)、post-(後に)、re-(再び・もとへ)、inter-(間に)。-ology(〜学)、-cide(殺す)、-phobia(恐怖症)。\n【文脈から推測する】知らない単語の前後で、言いかえ(or・that is・in other words)、対比(but・while・unlike)、例示(such as・for example)を探します。\n例:Some animals are nocturnal; that is, they are active at night.(夜行性の動物もいる。つまり、夜に活動する)→ that is の後ろから nocturnal=夜行性の、と分かります。\n推測した意味は、その文に当てはめて意味が通るかを必ず確かめます。',
        key: '知らない単語は、語の部品と、前後の言いかえ・対比・例示から意味を推測します。',
        ex: [{ q: '下線の語 erratic の意味を推測しよう。\nThe weather in this region is very erratic; one day it is hot, and the next day it is freezing.', hint: 'セミコロン(;)の後ろが、前の内容の説明になっています。', steps: ['セミコロンの後ろ:ある日は暑く、次の日はひどく寒い。', 'これは前の文「この地域の天気は very erratic だ」の具体的な説明になっている。', '「日によって大きく変わる」ようすなので、erratic=不安定な・変わりやすい、と推測できる。'], a: '不安定な・変わりやすい(この地域の天気はとても変わりやすい)', check: '推測した意味を文に当てはめて「この地域の天気はとても変わりやすい。ある日は暑く、次の日はひどく寒い」と自然につながるかを確かめます。' }] },
      { h: '下線部和訳の手順', t: '難関大では、構造の複雑な英文を日本語に訳す問題がよく出ます。ここでも、並べかえと同じく「V から考える」のが基本です。\n①時制をもつ動詞(V)をすべて探し、接続詞・関係詞・疑問詞の数を数えます。ふつう、V の数は、それらの数より1つ多くなります。\n②主節の S と V を決め、前置詞のかたまり・関係詞節・分詞のかたまりをかっこでくくります。\n③骨組みを直訳してから、かっこの中を説明として足していきます。\n④最後に、日本語として自然な語順・表現に整えます。ただし、英文にない内容を足したり、意味を変えたりする訳はしません。',
        key: '和訳は、V を数えて節の数を確かめ → 主節の骨組みを訳し → かっこの中を足す、の順に進めます。',
        ex: [{ q: '和訳しよう。\nWhat matters is not how much you know but how you use what you know.', hint: 'not A but B(A ではなく B)の形が文のどこにあるかを探します。', steps: ['V を探す:matters・is・know・use・know の5つ。what・how・how・what の4つが節を作るので、5=4+1 で数が合う。', '主節:S=What matters(大切なこと)、V=is。C は not A but B の形。', 'A=how much you know(どれだけ知っているか)、B=how you use what you know(知っていることをどう使うか)。', '「大切なのは、A ではなく B だ」と骨組みを訳し、A・B を入れる。'], a: '大切なのは、どれだけ多くのことを知っているかではなく、知っていることをどのように使うかである。', check: '訳の中に「大切なのは」「〜ではなく」「〜である」という骨組みが残っていて、A と B が対になっていることを確かめます。' }] }
    ],
    faq: [
      ['並べかえで、どうしても1語余ったり足りなかったりするときは?', '多くの場合、動詞の語法(後ろに何をとるか)か熟語のかたまりを見落としています。もう一度、V になる語と、その V が後ろに何をとるか(O・C・to 不定詞・前置詞など)を確かめましょう。\n日本語訳にない語が選択肢にあるときは、形式主語の it や、強調構文の that などの「訳に出ない語」であることが多いです。'],
      ['同格の that と関係代名詞の that は、訳し方もちがうの?', 'ちがいます。同格の that は「〜という(名詞)」と訳し、名詞の中身を説明します。the news that he won(彼が勝ったという知らせ)。\n関係代名詞の that は「〜する(名詞)」と訳します。the news that he told me(彼が私に話した知らせ)。'],
      ['準1級レベルの単語は、全部覚えるべき?', '全部を覚える必要はありません。長文に出る難しい語の多くは、語の部品や前後の言いかえ・対比から意味を推測できます。\nまずは共通テストレベルの単語を確実にし、そのうえで、よく出る語源(spect・port・dict など)を使って語彙を広げるのが効率的です。']
    ],
    terms: [['並べかえ問題', '与えられた語を正しい英文に並べる問題。まず V と S を決める'], ['語法', '動詞などが後ろにどんな形をとるかの決まり'], ['同格の that', '名詞の内容を説明する that 節。後ろは完全な文'], ['補語の倒置', 'C + V + S の語順。長い主語を後ろに回す'], ['接頭辞', '語の前につく部品(un-・pre-・re- など)'], ['語根', '語の中心となる意味をもつ部品']],
    miss: ['並べかえで、日本語の語順どおりに英語を並べてしまう。まず V を決め、その語法から並べます。', '名詞 + that を見ると、すべて関係代名詞だと思ってしまう。後ろが完全な文なら同格です。', 'rob と steal の語法を混同して、rob her bag や steal her of her bag としてしまう。rob は人、steal は物を O にとると覚えます。', '知らない単語で読むのを止めてしまい、前後の言いかえや対比を見ない。推測して読み進め、後で確かめます。'],
    sum: ['並べかえは V → S → かたまり → 文型の順。', '倒置・挿入は、もとの語順に戻して骨格を確かめる。', '名詞 + that 節は、後ろが完全なら同格、不完全なら関係代名詞。', 'rob A of B、prevent A from 〜ing などの語法は形ごと覚える。', '難しい単語は、語の部品と文脈から推測する。', '和訳は V を数えて節の数を確かめてから、骨組み → 説明の順に訳す。'],
    next: '次は「英単語・熟語(共通テストレベル)」です。語源や多義語を使った語彙の増やし方を学ぶと、難しい単語を推測する力の土台が固まります。'
  };

  // ===== 単語・熟語 =====
  L.e_h5 = {
    goal: '共通テストレベルの英単語を、語源・品詞の変化・多義語の知識を使って、効率よく覚えられるようになる。',
    intro: '英語の長文が読めない理由のいちばんは、【単語を知らないこと】です。共通テストでは、およそ4,000〜5,000語くらいの語彙があると読みやすくなると言われます。とても多く感じますが、単語には「部品」があり、1つの語から仲間の語がいくつも分かります。覚え方を工夫すれば、1語あたりの手間は大きく減らせます。',
    pre: '英単語には【品詞】があります。名詞(物・こと)、動詞(動作・状態)、形容詞(名詞のようす)、副詞(動詞などのようす)の4つが特に大切です。\n同じ意味の仲間でも、品詞がちがうと形が変わります。例:happy(幸せな:形容詞)→ happiness(幸福:名詞)→ happily(幸せに:副詞)\n英単語の発音は、つづりだけでは分からないことがあります。覚えるときは、音声を聞き、声に出しながら覚えると、リスニングにも強くなります。\n小学校・中学校で習う単語は、合わせて2,000語以上あります。高校では、それに加えてさらに多くの単語を覚えていきます。',
    secs: [
      { h: '覚え方の基本:少しずつ、何度も', t: '人は、覚えたことを時間とともに忘れていきます。でも、忘れかけたころに復習すると、記憶は前よりも長持ちするようになります。\nだから単語は、【1日に大量に覚えるより、少しずつを何度もくり返す】ほうが効果的です。\n1回目は、意味を確認して、発音しながら覚えます。翌日・3日後・1週間後には、もう一度テストして、まちがえた語だけを重点的に見直します。\n例文や長文の中で出会ったら、そこでも意味を思い出します。文の中で出会うと、使い方もいっしょに記憶に残ります。\n単語帳の「つづり → 意味」だけでなく、「長文の中で意味が思い出せるか」を目標にしましょう。',
        key: '単語は1日に大量に覚えるより、少しずつを「忘れかけたころ」に何度もくり返すほうが長く記憶に残ります。' },
      { h: '接頭辞と語根で覚える', t: '多くの英単語は、【接頭辞】(前の部品)+【語根】(中心の部品)+【接尾辞】(後ろの部品)からできています。\n【接頭辞】de(下へ・離れて)、re(再び・もとへ)、pre(前に)、ex(外へ)、in・im(中へ/否定)、con・com(いっしょに)、sub(下に)、trans(越えて)、un(否定)\n【語根】port(運ぶ)、spect(見る)、dict(言う)、struct(建てる)、ject(投げる)\n例:import(中へ運ぶ → 輸入する)、export(外へ運ぶ → 輸出する)、transport(越えて運ぶ → 輸送する)\n例:inspect(中を見る → 調べる)、predict(前もって言う → 予言する)、construct(いっしょに建てる → 建設する)、decline(下へ傾く → 減少する・断る)\n部品の意味を知っていれば、初めて見る単語でも意味の見当がつきます。',
        key: '接頭辞(前の部品)と語根(中心の部品)の意味を組み合わせると、初めて見る単語の意味も推測できます。',
        ex: [{ q: '語の部品から、次の単語の意味を推測しよう。\n(1) unpredictable (2) reconstruct', hint: '単語を、接頭辞・語根・接尾辞に分けてみます。', steps: ['(1) un(否定)+ pre(前に)+ dict(言う)+ able(できる)。', '(1) 「前もって言うことができない」→ 予測できない(形容詞)。', '(2) re(再び)+ con(いっしょに)+ struct(建てる)。', '(2) 「再び建てる」→ 再建する・作り直す(動詞)。'], a: '(1) 予測できない (2) 再建する', check: '(1) は predict(予言する)に -able と un- がついた形、と見直しても同じ意味になることを確かめます。' }] },
      { h: '接尾辞で品詞が分かる', t: '【接尾辞】は、単語の品詞を決めることが多い部品です。意味が分からない単語でも、品詞が分かれば文の構造がとれます。\n名詞を作る:-tion、-ment、-ness、-ity(例:decision、development、kindness、ability)\n形容詞を作る:-able、-ful、-ous、-ive、-al(例:sustainable、careful、dangerous、active、natural)\n動詞を作る:-ize、-en、-fy(例:realize、widen、simplify)。副詞を作る:-ly(例:quickly)\nただし、-ly で終わっても friendly(親しみやすい)や lovely(かわいらしい)のように形容詞の語もあるので、文の中での位置でも確かめます。',
        key: '-tion・-ment は名詞、-able・-ous・-ive は形容詞、-ize・-fy は動詞、-ly はたいてい副詞です。',
        ex: [{ q: '次の単語の品詞を答えよう。\n(1) development (2) dangerous (3) simplify (4) carefully', hint: '単語の終わりの部分(接尾辞)に注目します。', steps: ['(1) -ment は名詞を作る接尾辞 → 名詞(発達・開発)。', '(2) -ous は形容詞を作る接尾辞 → 形容詞(危険な)。', '(3) -fy は動詞を作る接尾辞 → 動詞(単純にする)。', '(4) careful(形容詞)に -ly がついた形 → 副詞(注意深く)。'], a: '(1) 名詞 (2) 形容詞 (3) 動詞 (4) 副詞', check: 'もとの語(develop・danger・simple・care)と見比べて、接尾辞で品詞が変わっていることを確かめます。' }] },
      { h: '品詞の変化をセットで覚える', t: '1つの単語を覚えるときは、品詞の変化もいっしょに覚えます。長文でも、文法問題でもよく問われます。\ndecide(決める)→ decision(決定)→ decisive(決定的な)/imagine(想像する)→ imagination(想像力)、imaginary(想像上の)、imaginative(想像力豊かな)\nsucceed(成功する/あとを継ぐ)→ success(成功)、successful(成功した)/succession(連続・継承)、successive(連続する)\neconomy(経済)→ economic(経済の)、economical(節約になる・むだのない)\n特に、意味が分かれる形容詞(economic と economical、successful と successive など)はよくねらわれます。',
        key: 'economic(経済の)と economical(節約になる)のように、形が似て意味が分かれる語はセットで区別します。',
        ex: [{ q: '正しいほうを選ぼう。\n(1) It is more (economic / economical) to buy a large bottle.\n(2) The country is facing serious (economic / economical) problems.', hint: '「経済の」か「節約になる」か、どちらの意味が文に合うかを考えます。', steps: ['(1) 「大きいびんを買うほうが〜だ」→ お金の節約になる、という意味が合う → economical。', '(2) 「その国は深刻な〜問題に直面している」→ 経済に関する問題、という意味が合う → economic。', 'economic=経済の、economical=節約になる、と区別する。'], a: '(1) economical(大きいびんを買うほうが割安だ)(2) economic(その国は深刻な経済問題に直面している)', check: '(2) に economical を入れると「節約になる問題」となり、意味が通らないことを確かめます。' }] },
      { h: '多義語:いちばん大事な意味から広げる', t: '中学で習ったやさしい単語ほど、ちがう意味で長文に出てきます。中心のイメージから意味を広げて覚えます。\n【address】住所 →(相手に向けて話す)→ 演説する、(問題に)取り組む。例:The government must address this issue.(政府はこの問題に取り組まなければならない)\n【issue】問題(論点)、(雑誌の)号、発行する\n【run】走る → 経営する(run a shop)、(液体が)流れる\n【cover】おおう → (範囲を)ふくむ、取材する、(費用を)まかなう\n【case】場合、事例、事件、箱\n知っている意味で訳して文がおかしいときは、【別の意味】を疑いましょう。',
        key: '知っている意味で訳して文がおかしいときは、その単語の「別の意味」を疑います。',
        ex: [{ q: '次の文の address の意味を答えよう。\nThe meeting will address the problem of food waste.', hint: 'address の後ろに何が来ているか(目的語)を見ます。', steps: ['address を「住所」と訳すと、文の意味が通らない → 別の意味を考える。', 'address の後ろに the problem(問題)という目的語がある → 「(問題に)取り組む」。', '文全体:その会議は食品ロスの問題に取り組む予定だ。'], a: '(問題に)取り組む', check: 'address を deal with(〜を処理する・〜に取り組む)に置きかえても、意味が通ることを確かめます。' }] }
    ],
    faq: [
      ['単語は、つづりを書けるようにしないといけないの?', '目的によります。長文読解やリスニングのためなら、まずは「見て・聞いて意味が分かる」ことを優先します。\n英作文や記述問題でよく使う基本語は、つづりも書けるようにしておきましょう。'],
      ['語源で覚えると、かえって時間がかからない?', '最初は少し時間がかかりますが、部品を1つ覚えると、同じ部品をもつ語をまとめて覚えられます。spect(見る)を知っていれば、inspect・respect・spectator などの意味が推測しやすくなります。\nすべての語に使う必要はなく、覚えにくい語に使うのが効果的です。'],
      ['1日に何語くらい覚えればいいの?', '決まった数はありませんが、新しい語を少なめにして、復習の回数を多くするほうが記憶に残りやすくなります。\nたとえば、新しく覚えるのは1日30語でも、前日・3日前・1週間前に覚えた語を毎日見直す、のように、くり返しを計画に組みこみましょう。']
    ],
    terms: [['接頭辞', '単語の前につく部品。意味を加える(re-・pre-・un- など)'], ['語根', '単語の中心となる意味をもつ部品(port・spect・dict など)'], ['接尾辞', '単語の後ろにつく部品。品詞を決めることが多い(-tion・-able など)'], ['多義語', '1つの単語で複数の意味をもつ語'], ['派生語', 'もとの単語から、接頭辞・接尾辞をつけてできた語']],
    miss: ['1日にまとめて大量に覚え、その後復習しないので忘れてしまう。翌日・3日後・1週間後の復習を予定に入れます。', 'つづりと日本語訳を1対1で覚え、多義語の別の意味に気づかない。訳して文がおかしければ別の意味を疑います。', 'economic と economical など、似た形の形容詞の意味を区別しない。セットで例文ごと覚えます。', '接頭辞 in- をいつも「中へ」と考え、否定の in-(inactive=活動していない)に気づかない。前後の意味で判断します。'],
    sum: ['単語は「少しずつ、何度も」。忘れかけたころに復習する。', '接頭辞・語根・接尾辞の部品から意味を推測する。', '接尾辞で品詞が分かる(-tion=名詞、-ous=形容詞、-ize=動詞)。', '品詞の変化(decide・decision・decisive)をセットで覚える。', '多義語は中心のイメージから意味を広げる。'],
    next: '次は「熟語」です。単語を覚えたら、それらが組み合わさった熟語を「かたまり」として覚えると、長文の読み取りがいっそう速くなります。'
  };
  L.e_idiom = {
    goal: 'よく出る英熟語を「かたまり」として覚え、後ろにくる語の形(名詞・ing など)まで正しく使えるようになる。',
    intro: '英熟語は、いくつかの単語が組み合わさって1つの意味を表すものです。look は「見る」、forward は「前へ」ですが、look forward to は「〜を楽しみに待つ」という意味になります。熟語は1語1語の意味を足しても分からないことがあるので、【かたまりのまま、例文の中で覚える】のがコツです。さらに、後ろに何がくるかまで覚えると、文法問題にも強くなります。',
    pre: '【前置詞】は名詞の前に置く語(in、on、at、for、to、with など)、【副詞】は動詞などをくわしくする語です。熟語では up・down・out・off・away などの副詞がよく使われます。\n【to 不定詞】は「to + 動詞の原形」でした。一方、前置詞の to の後ろには、名詞か動名詞(〜ing)が来ます。go to school の to は前置詞です。\n【動名詞】は動詞の ing 形で「〜すること」です。前置詞の後ろに動詞を置くときは、必ず動名詞にします。例:Thank you for coming.(来てくれてありがとう)\n【代名詞】(it・them・him など)は、前に出た名詞を指す語です。熟語では、代名詞を置く位置に決まりがあります。',
    secs: [
      { h: '熟語の型を知る', t: '英熟語は、形によっていくつかの型に分けられます。型を知っておくと整理しやすくなります。\n【動詞 + 前置詞】look for(〜をさがす)、look after(〜の世話をする = take care of)、depend on(〜にたよる)、deal with(〜を処理する)\n【動詞 + 副詞】give up(あきらめる)、put off(延期する = postpone)、turn down(断る = reject)、carry out(実行する)、figure out(理解する・解決する)\n【動詞 + 副詞 + 前置詞】put up with(〜をがまんする = tolerate)、come up with(〜を思いつく)、look down on(〜を見下す)、catch up with(〜に追いつく)\n【be + 形容詞 + 前置詞】be afraid of(〜をこわがる)、be proud of(〜を誇りに思う)、be different from(〜とちがう)、be familiar with(〜をよく知っている)、be responsible for(〜に責任がある)\n型ごとにまとめて覚えると、後で学ぶ「代名詞の位置」などの決まりも理解しやすくなります。',
        key: '熟語は「動詞 + 前置詞」「動詞 + 副詞」「動詞 + 副詞 + 前置詞」「be + 形容詞 + 前置詞」の型で整理します。',
        ex: [{ q: '日本語に合うように ( ) に適語を入れよう。\n(1) 私は彼の失礼な態度をがまんできない。I can\'t put ( ) ( ) his rude behavior.\n(2) 彼女はよい考えを思いついた。She came ( ) ( ) a good idea.', hint: 'どちらも「動詞 + 副詞 + 前置詞」の3語の熟語です。', steps: ['(1) 「〜をがまんする」は put up with。', '(1) put の後ろに up(副詞)、with(前置詞)を続ける。', '(2) 「〜を思いつく」は come up with。came は come の過去形。'], a: '(1) up / with (2) up / with', check: '(1) を I can\'t tolerate his rude behavior. と1語の動詞で言いかえても意味が同じになることを確かめます。' }] },
      { h: '1語の動詞で言いかえる', t: '熟語は、同じ意味の1語の動詞で言いかえられることがよくあります。入試の言いかえ問題でよく出ます。\ntake part in = participate in(〜に参加する)、put off = postpone(延期する)、call off = cancel(中止する)\nput up with = tolerate・stand・bear(〜をがまんする)、turn down = reject・refuse(断る)\nlook into = investigate(調査する)、make up for = compensate for(〜の埋め合わせをする)、bring up = raise(育てる)\n1語の動詞を覚えると、長文の中で言いかえに気づきやすくなります。内容一致問題では、本文の熟語が選択肢で1語の動詞に言いかえられていることがよくあります。',
        key: 'put off = postpone、turn down = reject のように、熟語と1語の動詞をセットで覚えます。',
        ex: [{ q: '同じ意味になるように、( ) に1語の動詞を入れよう。\n(1) The meeting was put off until next week. = The meeting was ( ) until next week.\n(2) They turned down our offer. = They ( ) our offer.', hint: 'put off と turn down の意味を、まず日本語で確かめます。', steps: ['(1) put off=延期する。1語なら postpone。', '(1) 受動態 was put off なので、過去分詞 postponed にする。', '(2) turn down=断る。1語なら reject(または refuse)。', '(2) 過去の文なので rejected(refused)。'], a: '(1) postponed(会議は来週まで延期された)(2) rejected(または refused)(彼らは私たちの申し出を断った)', check: '書きかえた文で、時制と受動態の形(was postponed)がもとの文と同じになっているかを確かめます。' }] },
      { h: 'to の後ろに ing がくる熟語', t: '熟語の中の【to が前置詞】のときは、後ろに名詞か動名詞(〜ing)がきます。to 不定詞(to + 原形)とまちがえやすいので要注意です。\n【look forward to 〜ing】〜するのを楽しみに待つ。例:I\'m looking forward to seeing you.(あなたに会うのを楽しみにしています)× to see\n【be used to 〜ing】〜するのに慣れている。例:She is used to getting up early.(彼女は早起きに慣れている)\n【object to 〜ing】〜することに反対する/【when it comes to 〜ing】〜することになると/【What do you say to 〜ing?】〜するのはどうですか\n注意:【used to + 原形】(以前はよく〜した)は、これとは別の表現です。例:I used to get up early.(以前はよく早起きしていた)\nbe動詞があるかどうか、後ろが原形か ing かで見分けます。',
        key: 'look forward to・be used to・object to の to は前置詞なので、後ろは名詞か〜ing です。',
        ex: [{ q: '( ) 内の動詞を正しい形にしよう。\n(1) We are looking forward to ( hear ) from you.\n(2) My father used to ( play ) baseball when he was young.', hint: '(1) は to が前置詞かどうか、(2) は be動詞があるかどうかに注目します。', steps: ['(1) look forward to の to は前置詞 → 後ろは名詞か動名詞。', '(1) hear → hearing。', '(2) be動詞のない used to は「以前はよく〜した」→ 後ろは動詞の原形 play。'], a: '(1) hearing(お便りを楽しみにお待ちしています)(2) play(父は若いころ、よく野球をしていた)', check: '(1) の to の後ろに名詞を置いて looking forward to the party と言えることから、to が前置詞だと確かめられます。' }] },
      { h: '動詞 + 副詞の熟語と代名詞の位置', t: '【動詞 + 副詞】の熟語で目的語が【代名詞】(it・them・him など)のときは、代名詞を動詞と副詞の【間】に置きます。\n○ Turn off the light. / ○ Turn the light off.(名詞ならどちらでもよい)○ Turn it off. / × Turn off it.(代名詞は間に置く)\n例:Please put on your coat. → Please put it on.(それを着てください)\n一方、【動詞 + 前置詞】の熟語では、代名詞も前置詞の後ろに置きます。例:I\'m looking for my key. → I\'m looking for it.(× looking it for)\noff・on・up・down・out・away などは、副詞として使われることが多い語です。',
        key: '動詞 + 副詞の熟語で目的語が代名詞なら、動詞と副詞の間に置きます(turn it off)。',
        ex: [{ q: '正しいほうを選ぼう。\nThe music is too loud. Please (turn it down / turn down it).', hint: 'turn down の down が、副詞か前置詞かを考えます。', steps: ['turn down(音量を下げる)は「動詞 + 副詞」の熟語。turn the music down とも言えることから、down は副詞だと分かる。', '目的語は代名詞 it(=the music)。', '代名詞は動詞と副詞の間に置く → turn it down。'], a: 'turn it down(音楽がうるさすぎます。音量を下げてください)', check: '名詞にもどすと turn down the music・turn the music down のどちらも言えることで、down が副詞だと確かめられます。' }] },
      { h: '前置詞のかたまりの熟語', t: '2語以上で1つの前置詞のようにはたらく熟語があります。これを【群前置詞】といい、後ろには名詞(または動名詞)が来ます。\nbecause of(〜のために)、in spite of(〜にもかかわらず = despite)、instead of(〜の代わりに)、according to(〜によれば)、thanks to(〜のおかげで)、in addition to(〜に加えて)\nbecause・though などの【接続詞】とちがい、後ろに S + V の文は置けません。× because of it rained → ○ because it rained / because of the rain\n例:In spite of the rain, they played soccer.(雨にもかかわらず、彼らはサッカーをした)= Though it was raining, they played soccer.\ndespite は1語で in spite of と同じ意味ですが、despite of とは言いません。',
        key: '群前置詞(because of・in spite of など)の後ろは名詞。S + V の文が続くなら接続詞(because・though)を使います。',
        ex: [{ q: '正しいほうを選ぼう。\n(1) We stayed home (because / because of) the heavy snow.\n(2) (Though / Despite) he was tired, he kept working.', hint: '( ) の後ろが名詞か、S + V の文かを見ます。', steps: ['(1) 後ろは the heavy snow という名詞 → 前置詞のはたらきをする because of。', '(2) 後ろは he was tired という S + V の文 → 接続詞が必要。', '(2) despite は前置詞なので文は続けられない → 接続詞 Though。'], a: '(1) because of(大雪のために、私たちは家にいた)(2) Though(彼は疲れていたけれども、働き続けた)', check: '(2) を Despite を使って言うなら Despite being tired, he kept working. のように、後ろを名詞(動名詞)にする必要があることを確かめます。' }] }
    ],
    faq: [
      ['熟語は何個くらい覚えればいいの?', '共通テストや一般的な入試なら、まずは熟語帳1冊の基本レベルを確実にするのが目標です。\n数をこなすより、例文ごと覚えて「後ろに何が来るか」まで言えるようにするほうが、得点につながります。'],
      ['to が前置詞か不定詞か、どう見分けるの?', 'to の後ろに名詞(the party など)を置いて意味が通るかを試します。I\'m looking forward to the party. と言えるなら、その to は前置詞で、動詞を置くときは〜ing にします。\nI want to the party. とは言えないので、want to の to は不定詞です。'],
      ['動詞 + 副詞と動詞 + 前置詞は、どう見分けるの?', '目的語を間にはさめるかどうかで見分けます。turn the light off と言える turn off は「動詞 + 副詞」、look the key for とは言えない look for は「動詞 + 前置詞」です。\n迷ったら、辞書で、その語が副詞として使われているかを確かめましょう。']
    ],
    terms: [['句動詞', '動詞 + 前置詞・副詞で1つの意味を表すもの(look for、give up など)'], ['前置詞の to', '後ろに名詞・動名詞がくる to。look forward to など'], ['to 不定詞', 'to + 動詞の原形'], ['言いかえ', '熟語と同じ意味の1語(put off = postpone など)'], ['群前置詞', '2語以上で1つの前置詞のようにはたらく語(because of・in spite of など)']],
    miss: ['look forward to see のように、前置詞の to の後ろに原形を置いてしまう。to の後ろに名詞を置けるかで確かめます。', 'be used to 〜ing(慣れている)と used to + 原形(以前はよく〜した)を混同する。be動詞の有無で見分けます。', 'turn off it のように、代名詞を副詞の後ろに置いてしまう。代名詞は動詞と副詞の間に置きます。', 'because of の後ろに S + V を続けてしまう。後ろが文なら because、名詞なら because of にします。'],
    sum: ['熟語は、かたまりのまま例文の中で覚える。', '1語の動詞での言いかえ(put off = postpone)もセットで覚える。', 'look forward to・be used to・object to の to は前置詞 → 後ろは〜ing。', '動詞 + 副詞の熟語で、代名詞は間に置く(turn it off)。', '群前置詞の後ろは名詞、S + V なら接続詞。'],
    next: '次は「長文読解(論理マーカー)」です。単語・熟語の知識を、However・For example などの「道しるべ」と組み合わせると、長い英文でも要点を速くつかめるようになります。'
  };

  // ===== 長文読解 =====
  L.e_h6 = {
    goal: '論理マーカー(However・For example・Therefore など)と段落の構造を手がかりに、英語の長文の要点を速く正確に読み取れるようになる。',
    intro: '英語の長文は、ただ単語を順番に訳していくと、何が言いたい文章なのか分からなくなってしまいます。英語の文章には、【話の流れを知らせる道しるべ】があります。それが However(しかし)、For example(たとえば)、Therefore(したがって)などの【論理マーカー】です。道しるべに印をつけながら読むと、次に何が来るかを予想でき、筆者の主張がどこにあるかも見えてきます。',
    pre: '【接続詞】(and・but・so・because など)は、文と文の関係を表す語でした。and は「追加」、but は「反対」、so は「結果」、because は「理由」を表します。\n【段落(パラグラフ)】は、いくつかの文がまとまって1つの話題を述べるかたまりです。英語では、段落の最初の行を少し下げて(または1行あけて)書き始めます。\n日本語の作文でも、「主張 → 理由 → 具体例 → まとめ」という順で書くと伝わりやすいと習いました。英語の文章も、同じような型で書かれています。\n【抽象】(まとめた言い方)と【具体】(くわしい例)の区別も大切です。「果物が好きだ」は抽象、「りんごやみかんが好きだ」は具体です。',
    secs: [
      { h: '論理マーカーの種類', t: '論理マーカーは、はたらきごとに覚えます。\n【逆接・対比】前と反対のことを言う。However(しかし)、But、Yet、Nevertheless(それにもかかわらず)、On the other hand(一方で)、In contrast(対照的に)\n【追加】前と同じ方向の内容を付け足す。In addition(さらに)、Moreover、Furthermore、Also、Besides\n【例示】前の内容の具体例を挙げる。For example、For instance(たとえば)、such as(〜のような)\n【因果・結論】前の内容から導かれる結果・結論。Therefore(したがって)、Thus、As a result(その結果)、Consequently、So\n【言いかえ・まとめ】前の内容を別の言葉で言う・まとめる。In other words(言いかえれば)、That is(つまり)、In short(要するに)、In conclusion(結論として)。【順序】First、Second、Then、Finally(最後に)',
        key: '論理マーカーは、逆接・追加・例示・因果・言いかえ のはたらきごとに覚えます。',
        ex: [{ q: '次の論理マーカーのはたらきを、逆接・追加・例示・因果から選ぼう。\n(1) Nevertheless (2) Moreover (3) Consequently (4) For instance', hint: '日本語の意味を思い出してから、はたらきを考えます。', steps: ['(1) Nevertheless=それにもかかわらず → 前と反対の内容が続く → 逆接。', '(2) Moreover=さらに → 同じ方向の内容を付け足す → 追加。', '(3) Consequently=その結果 → 前の内容から導かれる結果 → 因果。', '(4) For instance=たとえば → 具体例を挙げる → 例示。'], a: '(1) 逆接 (2) 追加 (3) 因果 (4) 例示', check: 'それぞれ However・In addition・Therefore・For example に置きかえても、はたらきが同じになることを確かめます。' }] },
      { h: '主張はどこにあるか', t: '論理マーカーの中でも、筆者の主張を見つけるのに特に大切なのが次の2つの型です。\n【一般論 → However → 主張】「Many people believe that 〜(多くの人は〜と信じている)」「It is often said that 〜(よく〜と言われる)」で始まる文は、筆者が否定するための前置きであることが多いです。その後の However の後ろに、筆者の本当の主張が来ます。\n【譲歩 → 主張】「Of course 〜 / It is true that 〜(確かに〜)」で相手の意見を一度認めてから、「but / however」で自分の意見を述べる型です。主張は but の後ろにあります。\nまた、For example の後ろは具体例なので、主張そのものではありません。主張は具体例の【前】にある、抽象的な文に書かれています。',
        key: '主張は However・but の後ろと、具体例の前の抽象的な文にあります。一般論や「確かに〜」は前置きです。',
        ex: [{ q: '( A )〜( C ) に入る語を、However・For example・Therefore から選ぼう。\nMany people believe that playing video games is a waste of time. ( A ), recent studies suggest that some games can improve problem-solving skills. ( B ), players of puzzle games often have to plan several steps ahead. ( C ), games may be more useful than we think.', hint: '空所の前後の内容が「反対」「具体例」「結論」のどれにあたるかを考えます。', steps: ['(A) 前:ゲームは時間のむだだと信じられている。後:問題解決能力を高めるゲームもある → 反対の内容なので逆接 However。', '(B) 後ろの「パズルゲームでは何手も先を計画しなければならない」は、前の「問題解決能力を高める」の具体例 → For example。', '(C) 後ろの「ゲームは思っているより役に立つかもしれない」は、ここまでの内容から導かれる結論 → Therefore。', '筆者の主張は However の後ろと Therefore の後ろにある。'], a: '(A) However (B) For example (C) Therefore\n(訳)多くの人は、テレビゲームをすることは時間のむだだと信じている。しかし、最近の研究では、問題解決能力を高めるゲームもあることが示されている。たとえば、パズルゲームをする人は、何手も先を計画しなければならないことが多い。したがって、ゲームは私たちが思っているよりも役に立つのかもしれない。', check: '(A) の後ろと (C) の後ろをつなぐと「ゲームは役に立つ」という一貫した主張になることを確かめます。' }] },
      { h: '段落の構造:トピックセンテンスを探す', t: '英語の段落(パラグラフ)は、ふつう【1つの段落に1つの主題】という決まりで書かれています。段落は次の3つの部分からできていることが多いです。\n①【トピックセンテンス】その段落の主題(言いたいこと)を短く述べる文。段落の最初に来ることが多い。\n②【サポーティングセンテンス】主題を支える理由・具体例・説明。For example、In addition などで始まることが多い。\n③【コンクルーディングセンテンス】段落のまとめ。Therefore、Thus、In short などで始まることがある。\nこの構造を知っていると、時間がないときでも、【各段落の最初の文】と【論理マーカーの後ろ】を拾い読みするだけで、文章全体の流れがつかめます(パラグラフ・リーディング)。',
        key: '段落は「トピックセンテンス → サポート → まとめ」。まず各段落の最初の文に注目します。',
        ex: [{ q: '次の段落の主題(トピックセンテンス)はどれか。また、段落の要点を日本語で答えよう。\nSleep is essential for learning. When we sleep, the brain organizes the information we took in during the day. In one experiment, students who slept well after studying remembered more than those who stayed up all night. Thus, cutting sleep to study longer may actually hurt your grades.', hint: '段落の中で、いちばん抽象的で、ほかの文がそれを支えている文を探します。', steps: ['1文目「睡眠は学習に欠かせない」は抽象的で、段落全体の主題になっている → トピックセンテンス。', '2文目は理由の説明(脳が情報を整理する)、3文目は In one experiment で始まる具体例(実験)。どちらもサポーティングセンテンス。', '4文目は Thus(したがって)で始まるまとめ → コンクルーディングセンテンス。', '主題とまとめを合わせて、要点を短くまとめる。'], a: 'トピックセンテンス:Sleep is essential for learning.(睡眠は学習に欠かせない)\n要点:睡眠中に脳は情報を整理するので、勉強時間を増やすために睡眠をけずると、かえって成績が下がるおそれがある。', check: '2文目・3文目を消しても、1文目と4文目だけで段落の言いたいことが伝わるかを確かめます。' }] },
      { h: '本番での読み方の手順', t: '① 【設問を先に見る】何を問われているか(主旨・内容一致・理由など)を確認してから本文を読みます。\n② 【論理マーカーに印をつけながら読む】However・Therefore には丸、For example には下線など、自分で決めた印をつけます。\n③ 【マーカーの先を予想する】However を見たら「前と反対のことが来る」、For example を見たら「具体例が来る」と予想しながら読むと、速く読めます。\n④ 【段落ごとに一言でまとめる】段落を読み終えるたびに、余白に「〜の問題点」「〜の具体例」などと短くメモします。\n⑤ 【選択肢は本文の言いかえを探す】正解の選択肢は、本文の表現を別の言葉で言いかえていることが多いです。本文と同じ単語が多いだけの選択肢には注意しましょう。',
        key: '設問を先に見る → マーカーに印 → 先を予想 → 段落ごとにメモ → 言いかえの選択肢を探す、の順で読みます。' },
      { h: '言いかえの選択肢を見抜く', t: '内容一致問題では、正解の選択肢は、本文の表現を【別の言葉で言いかえて】いることがほとんどです。\nたとえば本文が It is not easy to learn a foreign language. なら、正解は Learning a foreign language is difficult. のように書かれます。not easy → difficult、to learn → learning と、意味は同じで形がちがいます。\n反対に、本文と同じ単語がたくさん使われているのに、一部だけが本文と食いちがう選択肢は、ひっかけであることが多いです。always・never・only・all などの「言い切る語」が入っている選択肢は、特に本文と照らし合わせて確かめます。\n選択肢を選ぶときは、①本文の該当箇所を探す、②選択肢と1語ずつ照らし合わせる、③「言いすぎ」や「本文に書かれていないこと」がないか確かめる、の順に進めます。',
        key: '正解は本文の「言いかえ」。同じ単語が多いだけの選択肢や、always・never などで言い切る選択肢に注意します。',
        ex: [{ q: '本文の内容に合うものを1つ選ぼう。\n本文:Although the new library is far from the station, it is always full of students because it has a large study space.\n① The library is close to the station.\n② Students like the library because they can study there.\n③ Students never visit the library because it is far.\n④ The library has only a small study space.', hint: '本文の because の後ろ(理由)が、どの選択肢で言いかえられているかを探します。', steps: ['本文:駅から遠いけれども、広い自習スペースがあるので、いつも学生でいっぱいだ。', '① close to the station(駅に近い)は、本文の far from the station と反対 → 不一致。③ never visit(決して訪れない)は always full of students と反対 → 不一致。', '④ only a small study space は、本文の a large study space と反対 → 不一致。', '② 「勉強できるので学生はその図書館を好む」は、「広い自習スペースがあるのでいつも学生でいっぱい」の言いかえ → 一致。'], a: '②', check: '② には本文と同じ単語(large・full など)がほとんどないのに意味が一致していて、「正解は言いかえ」という原則に合っていることを確かめます。' }] }
    ],
    faq: [
      ['論理マーカーがない段落は、どう読めばいいの?', 'マーカーがなくても、文と文の関係は必ずあります。「前の文の具体例かな」「前の文と反対のことかな」と、自分でマーカーを補いながら読むと流れがつかめます。\nまた、this・these・such などの指示語が何を指すかを確かめると、前の文とのつながりが見えてきます。'],
      ['パラグラフ・リーディングだけで問題は解けるの?', '文章全体の流れや主旨をつかむ問題には、とても有効です。ただし、細かい内容一致や下線部の意味を問う問題では、該当する部分をていねいに読む必要があります。\n「全体は速く、設問に関係する部分はていねいに」と、読む速さを使い分けましょう。'],
      ['However はいつも文頭に来るの?', '文頭に来ることが多いですが、The plan, however, failed.(しかし、その計画は失敗した)のように、文の途中にコンマではさんで置かれることもあります。どこにあっても「逆接」の意味は同じです。']
    ],
    terms: [['論理マーカー', '文と文、段落と段落の関係を示す語句(However・Therefore など)'], ['トピックセンテンス', '段落の主題を述べる文。段落の最初に来ることが多い'], ['サポーティングセンテンス', '主題を支える理由・具体例・説明の文'], ['譲歩', '相手の意見を「確かに〜」と一度認めること'], ['パラグラフ・リーディング', '各段落の主題をつかみながら、文章全体の流れを読む方法'], ['抽象と具体', 'まとめた言い方と、くわしい例。主張は抽象的な文に書かれることが多い']],
    miss: ['For example の後ろの具体例を、筆者の主張だと思ってしまう。主張は具体例の前の抽象的な文にあります。', '「Many people believe 〜」で始まる一般論を、筆者の意見だと思ってしまう。多くの場合、筆者はそれを However の後ろで否定します。', '本文と同じ単語が多い選択肢を、内容を確かめずに選んでしまう。正解は言いかえであることが多いと覚えておきます。', 'Nevertheless や On the other hand を、追加の意味だと思ってしまう。どちらも逆接・対比のマーカーです。'],
    sum: ['論理マーカーは 逆接・追加・例示・因果・言いかえ に分けて覚える。', 'However・but の後ろ、Therefore の後ろに主張や結論が来やすい。', '具体例の前にある抽象的な文が主張。', '段落は トピックセンテンス → サポート → まとめ。最初の文に注目する。', '設問を先に見て、マーカーに印をつけ、段落ごとにメモしながら読む。', '内容一致の正解は、本文の言いかえ。'],
    next: '仕上げとして「入試レベル:英文法・語法の総合」や「難関レベル:英語」に取り組み、文法の知識と長文の読み方を組み合わせて使う練習をしましょう。'
  };
})(WPS.LESSONS);
